const SECTOR_DEFAULT: usize = 64;

/// A simulated owner's shutdown grace (S8): its clients' pinned readers live in other processes,
/// which no single step can end, so a closing owner always waits out the grace.
const SERVICE_GRACE_MS: u64 = 1000;

/// The message and backtrace of the most recent panic, captured by the hook [`main`] installs so a
/// panicking step becomes a violation with its stack (the Go runner's `recover` + `debug.Stack`).
static LAST_PANIC: Mutex<String> = Mutex::new(String::new());

/// Run every trace named by `JED_SIM_IN`; nonzero exit if any trace failed.
pub fn main() -> ExitCode {
    let Ok(input) = std::env::var("JED_SIM_IN") else {
        eprintln!("sim: JED_SIM_IN not set (run through scripts/sim.rb)");
        return ExitCode::from(2);
    };
    let out = match std::env::var("JED_SIM_OUT") {
        Ok(o) if !o.is_empty() => PathBuf::from(o),
        _ => std::env::temp_dir().join(format!("jed-sim-{}", std::process::id())),
    };
    if let Err(e) = std::fs::create_dir_all(&out) {
        eprintln!("sim: {}: {e}", out.display());
        return ExitCode::from(2);
    }
    let paths = match trace_paths(&input) {
        Ok(p) => p,
        Err(e) => {
            eprintln!("sim: {input}: {e}");
            return ExitCode::from(2);
        }
    };
    let results_path = match std::env::var("JED_SIM_RESULTS") {
        Ok(r) if !r.is_empty() => PathBuf::from(r),
        _ => out.join("rust.results.jsonl"),
    };
    let mut results = match std::fs::OpenOptions::new()
        .create(true)
        .append(true)
        .open(&results_path)
    {
        Ok(f) => f,
        Err(e) => {
            eprintln!("sim: {}: {e}", results_path.display());
            return ExitCode::from(2);
        }
    };
    std::panic::set_hook(Box::new(|info| {
        let text = format!("{info}\n{}", std::backtrace::Backtrace::force_capture());
        *LAST_PANIC.lock().unwrap_or_else(|e| e.into_inner()) = text;
    }));
    let images = std::env::var("JED_SIM_IMAGES").is_ok_and(|v| !v.is_empty());
    let mut failed = false;
    for path in &paths {
        let res = run_file(path, &out, images);
        let _ = writeln!(results, "{}", res.json());
        if !res.violation.is_empty() {
            eprintln!("{}: {}", path.display(), res.violation);
            failed = true;
        }
    }
    if failed {
        ExitCode::FAILURE
    } else {
        ExitCode::SUCCESS
    }
}

fn trace_paths(input: &str) -> std::io::Result<Vec<PathBuf>> {
    let path = Path::new(input);
    if std::fs::metadata(path)?.is_dir() {
        let mut paths: Vec<PathBuf> = std::fs::read_dir(path)?
            .filter_map(|e| e.ok().map(|e| e.path()))
            .filter(|p| p.extension().is_some_and(|x| x == "sim"))
            .collect();
        paths.sort();
        return Ok(paths);
    }
    if input.ends_with(".sim") {
        return Ok(vec![path.to_path_buf()]);
    }
    let data = std::fs::read_to_string(path)?;
    Ok(data
        .split('\n')
        .map(str::trim)
        .filter(|l| !l.is_empty())
        .map(PathBuf::from)
        .collect())
}

// --- trace parsing ------------------------------------------------------------------------------

struct Step {
    line: usize,
    kind: String,
    /// open (the session's process), spawn, exit, kill, backup (when `has_pid`)
    pid: u32,
    /// Whether a `backup` step names its process; without one it runs in the lowest running.
    has_pid: bool,
    sid: String,
    mode: String,
    sql: String,
    params: HashMap<String, String>,
}

impl Step {
    fn int_param(&self, key: &str) -> i64 {
        self.params
            .get(key)
            .and_then(|v| v.parse().ok())
            .unwrap_or(0)
    }
}

struct Trace {
    header: HashMap<String, String>,
    steps: Vec<Step>,
}

impl Trace {
    fn header(&self, key: &str) -> &str {
        self.header.get(key).map_or("", String::as_str)
    }
}

fn parse(text: &str) -> Result<Trace, String> {
    let mut tr = Trace {
        header: HashMap::new(),
        steps: Vec::new(),
    };
    for (n, raw) in text.split('\n').enumerate() {
        let line = raw.trim_end_matches('\r');
        if line.trim().is_empty() {
            continue;
        }
        if let Some(rest) = line.strip_prefix('#') {
            if let Some((k, v)) = rest.trim().split_once(':') {
                tr.header.insert(k.trim().to_string(), v.trim().to_string());
            }
            continue;
        }
        let fields: Vec<&str> = line.split_whitespace().collect();
        let params = |st: &mut Step, kvs: &[&str]| -> Result<(), String> {
            for kv in kvs {
                let Some((k, v)) = kv.split_once('=') else {
                    return Err(format!("line {}: bad parameter {}", n + 1, go_quote(kv)));
                };
                st.params.insert(k.to_string(), v.to_string());
            }
            Ok(())
        };
        let mut st = Step {
            line: n + 1,
            kind: fields[0].to_string(),
            pid: 0,
            has_pid: false,
            sid: String::new(),
            mode: String::new(),
            sql: String::new(),
            params: HashMap::new(),
        };
        match fields[0] {
            "open" => {
                if fields.len() != 3 && fields.len() != 4 {
                    return Err(format!("line {}: open <sid> read|write [p<N>]", n + 1));
                }
                st.sid = fields[1].to_string();
                st.mode = fields[2].to_string();
                if fields.len() == 4 {
                    st.pid = parse_pid(fields[3]).map_err(|e| format!("line {}: {e}", n + 1))?;
                }
            }
            "spawn" | "exit" | "kill" | "disconnect" => {
                if fields.len() != 2 {
                    return Err(format!("line {}: {} p<N>", n + 1, st.kind));
                }
                st.pid = parse_pid(fields[1]).map_err(|e| format!("line {}: {e}", n + 1))?;
            }
            "on" => {
                if fields.len() < 3 {
                    return Err(format!("line {}: on <sid> <sql>", n + 1));
                }
                st.sid = fields[1].to_string();
                let rest = line["on".len()..].trim();
                st.sql = rest[st.sid.len()..].trim().to_string();
            }
            "commit" | "rollback" | "close" => {
                if fields.len() != 2 {
                    return Err(format!("line {}: {} <sid>", n + 1, st.kind));
                }
                st.sid = fields[1].to_string();
            }
            "fault" | "crash" => {
                if fields.len() < 2 {
                    return Err(format!("line {}: {} <kind> [k=v ...]", n + 1, st.kind));
                }
                st.mode = fields[1].to_string();
                params(&mut st, &fields[2..])?;
            }
            "clock" => {
                if fields.len() != 2 || !fields[1].starts_with('+') {
                    return Err(format!("line {}: clock +<micros>", n + 1));
                }
                st.params
                    .insert("delta".to_string(), fields[1][1..].to_string());
            }
            "attach" => {
                if fields.len() != 2 || fields[1] == "main" || fields[1] == "temp" {
                    return Err(format!("line {}: attach <name>", n + 1));
                }
                st.sid = fields[1].to_string();
            }
            "compact" => {
                if fields.len() > 2 {
                    return Err(format!("line {}: compact [<database>]", n + 1));
                }
                st.sid = fields.get(1).copied().unwrap_or("main").to_string();
            }
            "backup" => {
                if (fields.len() != 2 && fields.len() != 3)
                    || (fields[1] != "page_identical" && fields[1] != "compacted")
                {
                    return Err(format!(
                        "line {}: backup page_identical|compacted [p<N>]",
                        n + 1
                    ));
                }
                st.mode = fields[1].to_string();
                if fields.len() == 3 {
                    st.pid = parse_pid(fields[2]).map_err(|e| format!("line {}: {e}", n + 1))?;
                    st.has_pid = true;
                }
            }
            "change_key" | "rekey" => {
                // S12–S13: a credential change or rekey of main (or a file attachment) to
                // simulation key 1–3, or a rekey that decrypts it.
                let ok = (fields.len() == 2 || (fields.len() == 3 && fields[2] != "temp"))
                    && (matches!(fields[1], "1" | "2" | "3")
                        || (fields[1] == "plain" && st.kind == "rekey"));
                if !ok {
                    return Err(format!(
                        "line {}: {} 1|2|3|plain [<database>]",
                        n + 1,
                        st.kind
                    ));
                }
                st.mode = fields[1].to_string();
                st.sid = fields.get(2).copied().unwrap_or("main").to_string();
            }
            "replay" => {
                if fields.len() != 2 {
                    return Err(format!("line {}: replay <kind>", n + 1));
                }
                st.mode = fields[1].to_string();
            }
            "restore" => {
                let j: Option<i64> = fields[1..].concat().parse().ok();
                if fields.len() != 2 || j.is_none_or(|j| j < 1) {
                    return Err(format!("line {}: restore <j>", n + 1));
                }
                st.params.insert("j".to_string(), fields[1].to_string());
            }
            "corrupt" => params(&mut st, &fields[1..])?,
            "check" | "reopen" | "tick" => {}
            other => return Err(format!("line {}: unknown step {}", n + 1, go_quote(other))),
        }
        tr.steps.push(st);
    }
    if tr.header("format") != "simulation" {
        return Err("missing `# format: simulation` header".to_string());
    }
    Ok(tr)
}

/// Parse a process name, `p<N>`.
fn parse_pid(name: &str) -> Result<u32, String> {
    name.strip_prefix('p')
        .and_then(|n| n.parse::<u32>().ok())
        .ok_or_else(|| format!("bad process {} (want p<N>)", go_quote(name)))
}

/// The fault a `fault` step arms (simulation-testing.md §6.3).
fn fault_of(st: &Step) -> Result<Fault, String> {
    match st.mode.as_str() {
        "power_loss" => {
            let mut f = Fault::new(FaultKind::PowerLoss);
            f.survive = st.int_param("survive");
            f.tear = st.int_param("tear");
            f.nth = st.int_param("nth");
            return Ok(f);
        }
        "process_crash" => {
            let mut f = Fault::new(FaultKind::ProcessCrash);
            f.issue = st.int_param("issue");
            f.nth = st.int_param("nth");
            return Ok(f);
        }
        "io_error" => match st.params.get("op").map(String::as_str) {
            Some("write") => {
                let mut f = Fault::new(FaultKind::IoWrite);
                f.p = st.int_param("p");
                return Ok(f);
            }
            Some("sync") => {
                let mut f = Fault::new(FaultKind::IoSync);
                f.nth = st.int_param("nth");
                return Ok(f);
            }
            _ => {}
        },
        "read_error" => {
            let mut f = Fault::new(FaultKind::ReadError);
            f.p = st.int_param("p");
            return Ok(f);
        }
        "enospc" => return Ok(Fault::new(FaultKind::Enospc)),
        "spill_error" => {
            let mut f = Fault::new(FaultKind::SpillError);
            f.p = st.int_param("p");
            return Ok(f);
        }
        "disconnect" => {
            let mut f = Fault::new(FaultKind::Disconnect);
            f.nth = st.int_param("nth");
            return Ok(f);
        }
        _ => {}
    }
    let mut params: Vec<_> = st.params.iter().collect();
    params.sort();
    Err(format!(
        "line {}: unsupported fault {} {:?}",
        st.line, st.mode, params
    ))
}

// --- output formatting --------------------------------------------------------------------------

/// Go's `%q` for the ASCII strings a transcript carries (session ids, SQLSTATEs, kinds, digests).
fn go_quote(s: &str) -> String {
    let mut out = String::with_capacity(s.len() + 2);
    out.push('"');
    for c in s.chars() {
        match c {
            '"' => out.push_str("\\\""),
            '\\' => out.push_str("\\\\"),
            '\n' => out.push_str("\\n"),
            '\r' => out.push_str("\\r"),
            '\t' => out.push_str("\\t"),
            c if (c as u32) < 0x20 || c as u32 == 0x7f => {
                let _ = write!(out, "\\x{:02x}", c as u32);
            }
            c => out.push(c),
        }
    }
    out.push('"');
    out
}

/// A JSON string literal (the results file is parsed, never compared byte-wise).
fn json_quote(s: &str) -> String {
    let mut out = String::with_capacity(s.len() + 2);
    out.push('"');
    for c in s.chars() {
        match c {
            '"' => out.push_str("\\\""),
            '\\' => out.push_str("\\\\"),
            '\n' => out.push_str("\\n"),
            '\r' => out.push_str("\\r"),
            '\t' => out.push_str("\\t"),
            c if (c as u32) < 0x20 => {
                let _ = write!(out, "\\u{:04x}", c as u32);
            }
            c => out.push(c),
        }
    }
    out.push('"');
    out
}

// --- the run ------------------------------------------------------------------------------------

struct SimResult {
    name: String,
    steps: usize,
    violation: String,
    violation_step: i64,
    transcript_hash: u64,
    ops_hash: u64,
}

impl SimResult {
    fn json(&self) -> String {
        let status = if self.violation.is_empty() {
            "pass"
        } else {
            "fail"
        };
        format!(
            "{{\"trace\":{},\"core\":\"rust\",\"status\":\"{status}\",\"steps\":{},\"violation\":{},\"violation_step\":{},\"transcript_hash\":\"{:016x}\",\"ops_hash\":\"{:016x}\"}}",
            json_quote(&self.name),
            self.steps,
            json_quote(&self.violation),
            self.violation_step,
            self.transcript_hash,
            self.ops_hash
        )
    }
}

/// Run one trace twice — the second run is the self-determinism check (§8.5) — and write the first
/// run's transcript (and, on a violation, the crash image) under `out`.
fn run_file(path: &Path, out: &Path, images: bool) -> SimResult {
    let base = path
        .file_name()
        .map(|n| n.to_string_lossy().into_owned())
        .unwrap_or_default();
    let name = base.strip_suffix(".sim").unwrap_or(&base).to_string();
    let mut res = SimResult {
        name: name.clone(),
        steps: 0,
        violation: String::new(),
        violation_step: -1,
        transcript_hash: 0,
        ops_hash: 0,
    };
    let data = match std::fs::read_to_string(path) {
        Ok(d) => d,
        Err(e) => {
            res.violation = format!("read trace: {e}");
            return res;
        }
    };
    let tr = match parse(&data) {
        Ok(t) => t,
        Err(e) => {
            res.violation = format!("parse trace: {e}");
            return res;
        }
    };
    let artifact = |suffix: &str| out.join(format!("{name}.rust.{suffix}"));
    let mut first = Runner::new(&tr);
    if images {
        first.image_prefix = Some(out.join(format!("{name}.rust")));
    }
    first.run();
    res.steps = tr.steps.len();
    res.transcript_hash = fnv(first.transcript.as_bytes());
    res.ops_hash = first.ops();
    let _ = std::fs::write(artifact("jsonl"), &first.transcript);
    if !first.violation.is_empty() {
        res.violation = first.violation.clone();
        res.violation_step = first.violation_step;
        for (file, text) in &first.diagnostics {
            let _ = std::fs::write(artifact(file), text);
        }
        if !first.stack.is_empty() {
            let _ = std::fs::write(artifact("stack.txt"), &first.stack);
        }
        if let Some(image) = &first.crash_image {
            let _ = std::fs::write(artifact("crash.img"), image);
        }
        return res;
    }
    let mut second = Runner::new(&tr);
    second.run();
    if !second.violation.is_empty() {
        res.violation = format!(
            "nondeterministic: the second run failed: {}",
            second.violation
        );
        res.violation_step = second.violation_step;
    } else if second.transcript != first.transcript {
        res.violation = format!(
            "nondeterministic: transcripts differ between two runs{}",
            first_diff(&first.transcript, &second.transcript)
        );
    } else if second.ops() != first.ops() {
        res.violation =
            "nondeterministic: storage operation logs differ between two runs".to_string();
    }
    res
}

fn first_diff(a: &str, b: &str) -> String {
    for (x, y) in a.split('\n').zip(b.split('\n')) {
        if x != y {
            return format!(" (first difference:\n  {x}\n  {y})");
        }
    }
    String::new()
}

/// The simulator's random source: each trace session has its own seeded stream, and a draw comes
/// from the stream of the session whose step is running (the simulator runs one step at a time).
/// Outside any session's step it falls back to OS entropy, which no oracle query draws.
struct SimRandom {
    current: Mutex<Option<Arc<SeededRandom>>>,
}

impl RandomSource for SimRandom {
    fn fill(&self, buf: &mut [u8]) -> Result<(), EngineError> {
        let current = self
            .current
            .lock()
            .unwrap_or_else(|e| e.into_inner())
            .clone();
        match current {
            Some(stream) => stream.fill(buf),
            None => crate::seam::os_random_source().fill(buf),
        }
    }
}

/// The simulator's clock source: the simulated clock (§7).
struct SimClock(Arc<AtomicI64>);

impl ClockSource for SimClock {
    fn now_micros(&self) -> i64 {
        self.0.load(Ordering::Relaxed)
    }
}

struct SimSession {
    s: Session,
    /// The session's own seeded random stream (seeded from the trace seed and the open step), which
    /// the environment's random source draws from while a step on this session runs.
    random: Arc<SeededRandom>,
    write: bool,
    /// The version of each database a read session pinned (§8.1: what it must keep seeing).
    pins: HashMap<String, u64>,
    /// The process the session lives in.
    pid: u32,
}

/// One simulated process: a Database over the shared simulated filesystem (in a service trace, its
/// own lock host over the simulated lock table and network — S8).
struct Proc {
    db: Database,
    /// The Environment it opened with ([`Runner::new_env`]).
    env: Environment,
}

/// One database's oracle state (simulation-testing.md §8.1–8.3): main, or a file attachment (S4),
/// each with its own versions, history, and durability floor.
struct SimDb {
    /// Its file in the simulated filesystem.
    file: String,
    /// version → digests of every generation attempted at it
    history: HashMap<u64, HashSet<String>>,
    /// The published version.
    version: u64,
    /// Its digest.
    last_digest: String,
    /// Recovery may never return an older version; 0: the file may vanish ...
    floor: u64,
    /// ... nor a newer one than was ever attempted.
    max_attempted: u64,

    // Bounded growth (§8.3), tracked over one process lifetime: an upper bound on the live count the
    // engine's reclamation trigger compares against, and what the previous commit left.
    /// The page high-water now.
    high: u32,
    /// The free list the next commit allocates from.
    free: u32,
    /// Where that free list's trailing run below `high` starts (`high`: none).
    trail: u32,
    /// ≥ the engine's live-at-last-reclamation.
    lac_bound: u32,
    /// The previous commit in this lifetime.
    last: Growth,
    /// Whether the current step began with a relaxed batch pending on this database's file: its
    /// commit allocates from the high-water and keeps the batch's pages off the free list
    /// (validated-cow.md §4), so the bounded-growth assertions do not apply to it.
    batch_open: bool,
    /// Whether the step began with a non-empty pending set: a commit then plans inside a batch and
    /// may not lower the high-water (validated-cow.md §4). Unlike `batch_open` it is false after a
    /// recovery whose adopted generation awaits stabilization, which the commit's own first barrier
    /// makes the floor.
    batch_pending: bool,
    /// The simulated-clock deadline of the batch pending on this database's file (validated-cow.md
    /// §4.1): the clock of the step that started it plus the trace's flush interval.
    deadline: i64,
    /// Whether the step began with that batch past its deadline: a commit of this database in the
    /// step must flush it first.
    due: bool,
    /// Set when a relaxed commit lowered the high-water: the next flush (the batch cap, close) must
    /// shorten the file (format.md *Trailing truncation*).
    shrink_due: bool,
    /// Set when an owner died: until a process observes the database again, it may have recovered
    /// any version from the floor up.
    owner_lost: bool,

    /// Encryption at rest (S12–S13): the simulation key the database is encrypted under
    /// ([`SIM_KEYS`]), or -1 when it is plaintext.
    key: i32,
    /// A credential change or rekey of this step, which recovery after it checks the file against.
    key_change: Option<KeyChange>,
}

/// A key step in progress: the key before it and the one it installs. When the file's directory
/// entry was not durable as it began (an earlier compaction's or rekey's rename awaits the next
/// opener's directory barrier), a power loss may bring an older file back under an older key.
#[derive(Clone, Copy)]
struct KeyChange {
    old: i32,
    next: i32,
    entry_pending: bool,
}

/// A successful backup of main (S13): its file, the version and contents a new process opens
/// there, and the key main had when it was taken.
struct SimBackup {
    n: usize,
    file: String,
    version: u64,
    digest: String,
    key: i32,
}

/// What a commit left behind, for the next commit's bounded-growth check.
#[derive(Clone, Copy, Default)]
struct Growth {
    /// A quiet commit that must have reclaimed: its free list holds every dead page.
    reclaimed: bool,
    /// Its page high-water.
    high: u32,
    /// Its free-list length.
    free: u32,
}

impl SimDb {
    fn new(file: &str) -> SimDb {
        SimDb {
            file: file.to_string(),
            history: HashMap::new(),
            version: 0,
            last_digest: String::new(),
            floor: 0,
            max_attempted: 0,
            high: 0,
            free: 0,
            trail: 0,
            lac_bound: 0,
            last: Growth::default(),
            batch_open: false,
            batch_pending: false,
            deadline: 0,
            due: false,
            shrink_due: false,
            owner_lost: false,
            key: -1,
            key_change: None,
        }
    }

    fn add_history(&mut self, v: u64, d: String) {
        self.history.entry(v).or_default().insert(d);
    }

    fn in_history(&self, v: u64, d: &str) -> bool {
        self.history.get(&v).is_some_and(|set| set.contains(d))
    }
}

/// The result of one logical digest: the hash (`None` if a query failed), the text folded (or, on a
/// failure, what was folded plus the error), and why it failed.
struct Digest {
    hash: Option<String>,
    text: String,
    err: Option<EngineError>,
}

/// The simulation's host keys (S12): key `n` is 32 bytes of `0x4A + n`, so key 0 is the goldens'
/// (spec/fileformat/verify.rb tries all four on an encrypted image).
static SIM_KEYS: std::sync::LazyLock<[Credential; 4]> =
    std::sync::LazyLock::new(|| [0u8, 1, 2, 3].map(|n| Credential::Key([0x4A + n; 32])));

/// Simulation key `k`'s credential, or none for -1, plaintext.
fn sim_credential(k: i32) -> Option<&'static Credential> {
    (k >= 0).then(|| &SIM_KEYS[k as usize])
}

struct Runner<'a> {
    tr: &'a Trace,
    seed: u64,
    page_size: u32,
    cache_bytes: i64,
    /// The simulated clock (§7), which the environment's clock source reads.
    clock: Arc<AtomicI64>,
    /// The random source every process's Environment ([`Runner::new_env`]) holds: it draws from the
    /// stream of the session the current step runs on.
    random: Arc<SimRandom>,

    // Handle settings from the header (simulation-testing.md §5, slice S3), applied at every open.
    /// A session's work_mem.
    work_mem: i64,
    /// A session's temp_buffers: past it, a temp domain spills (temp-tables.md §6).
    temp_buffers: i64,
    /// A trace session's max_query_memory_bytes (the oracles' own reads are unlimited).
    max_query_memory: i64,
    /// The database's max_storage_bytes.
    max_storage_bytes: i64,
    /// The header's synchronous = off (validated-cow.md §4): every process batches its barriers,
    /// flushing inline so the barrier lands in the step that reached the batch cap.
    relaxed: bool,
    /// The header's flush_interval_ms (validated-cow.md §4.1; absent: 0, no time-based flush),
    /// measured on the simulated clock with no idle flusher.
    flush_interval_ms: u64,

    sessions: HashMap<String, SimSession>,
    /// The database of the process running the current step.
    db: Option<Database>,
    fs: Arc<Mutex<SimFs>>,

    // Processes (simulation-testing.md §14 S8). A single-process trace has only p0, opened without
    // coordination; a `# processes: service` trace opens every process under the page service, over
    // the simulated lock host and network: the first is the owner, later ones its clients.
    service: bool,
    net: Arc<SimNet>,
    procs: BTreeMap<u32, Proc>,
    /// The process running the current step.
    cur: u32,
    locks: Option<locks::SharedTable>,
    armed: Option<Fault>,

    transcript: String,

    /// Oracle state (simulation-testing.md §8.1–8.3), one per database: main, and each file
    /// attachment (S4).
    dbs: BTreeMap<String, SimDb>,

    violation: String,
    violation_step: i64,
    crash_image: Option<Vec<u8>>,
    /// The stack of a panic violation.
    stack: String,

    /// The text the most recent digest folded.
    last_digest_text: String,
    /// Why the most recent digest failed.
    digest_err: Option<EngineError>,
    /// Artifact name → contents, written on a violation.
    diagnostics: Vec<(String, String)>,
    /// When set, each recovery's image is written to `<prefix>.step<N>[.<db>].img`.
    image_prefix: Option<PathBuf>,
    /// Backup steps run, naming each destination.
    backups: usize,

    // Encryption at rest (slices S12–S13, spec/fileformat/encrypted.md): an encrypted trace creates
    // main and every attachment encrypted, seals every process's scratch files, and gives each
    // process opening its own seeded key-entropy stream. Each database's key is its SimDb's.
    encrypted: bool,
    /// Environments built so far, each a process opening ([`Runner::new_env`]).
    opens: u64,
    /// Main's successful backups in order, the ones a restore may copy back (S13).
    backups_ok: Vec<SimBackup>,
    /// The step running, for [`Runner::reopen_stale`]'s transcript line.
    step_index: usize,
}

fn engine_code(e: &EngineError) -> String {
    e.code().to_string()
}

/// The catalog part of the logical digest (§8.1).
const DIGEST_RELATIONS: [&str; 5] = [
    "jed_tables",
    "jed_columns",
    "jed_indexes",
    "jed_constraints",
    "jed_sequences",
];

/// Run `sql` and fold its rendered rows, sorted (row order is not what this harness tests), into an
/// FNV-1a hash: `(rows, affected, hash, cost)`.
fn sim_query(s: &mut Session, sql: &str) -> Result<(usize, i64, u64, i64), EngineError> {
    let mut rows = s.query(sql, &[])?;
    let mut rendered: Vec<String> = Vec::new();
    for row in &mut rows {
        let mut cells = Vec::with_capacity(row.len());
        for v in &row {
            cells.push(s.render(v)?);
        }
        rendered.push(cells.join("\x1f"));
    }
    rows.error()?;
    rendered.sort();
    let affected = rows.rows_affected().unwrap_or(-1);
    Ok((
        rendered.len(),
        affected,
        fnv(rendered.join("\x1e").as_bytes()),
        rows.cost(),
    ))
}

/// Fold one digest query's sorted rendered rows into `b`, collecting `jed_tables` names into
/// `tables`. `Err` carries the diagnostic text the Go reference keeps for that failure, and the
/// error.
fn digest_fold(
    s: &mut Session,
    sql: &str,
    b: &mut String,
    tables: &mut Vec<String>,
) -> Result<(), (String, EngineError)> {
    let mut rows = match s.query(sql, &[]) {
        Ok(r) => r,
        Err(e) => return Err((format!("{b}{sql}\nERROR: {e}\n"), e)),
    };
    let mut rendered: Vec<String> = Vec::new();
    for row in &mut rows {
        let mut cells = Vec::with_capacity(row.len());
        for v in &row {
            match s.render(v) {
                Ok(t) => cells.push(t),
                Err(e) => return Err((String::new(), e)),
            }
        }
        if sql.ends_with("jed_tables") {
            tables.push(cells[0].clone());
        }
        rendered.push(cells.join("\x1f"));
    }
    if let Err(e) = rows.error() {
        return Err((format!("{b}{sql}\nERROR: {e}\n"), e));
    }
    rendered.sort();
    b.push_str(sql);
    b.push('\n');
    b.push_str(&rendered.join("\n"));
    b.push_str("\n\n");
    Ok(())
}

/// The prefix that names database `name`'s relations: none for main, `name.` for an attachment.
fn qualifier(name: &str) -> String {
    if name == "main" {
        String::new()
    } else {
        format!("{name}.")
    }
}

/// The digest of a freshly created database (an attachment's version 1): every catalog relation
/// empty and no table.
fn empty_digest(name: &str) -> String {
    let q = qualifier(name);
    let mut b = String::new();
    for rel in DIGEST_RELATIONS {
        b.push_str(&format!("SELECT * FROM {q}{rel}\n\n\n"));
    }
    format!("{:016x}", fnv(b.as_bytes()))
}

/// The logical digest of what `s` sees of database `name`: the catalog relations plus every
/// table's rows, all rendered and sorted, folded with FNV-1a.
fn digest(s: &mut Session, name: &str) -> Digest {
    // The oracle's own reads must not trip a trace session's memory limit.
    let limit = s.max_query_memory_bytes();
    if limit > 0 {
        s.set_max_query_memory_bytes(0);
    }
    let result = digest_unlimited(s, &qualifier(name));
    if limit > 0 {
        s.set_max_query_memory_bytes(limit);
    }
    result
}

fn digest_unlimited(s: &mut Session, q: &str) -> Digest {
    let mut b = String::new();
    let mut tables: Vec<String> = Vec::new();
    let failed = |(text, e): (String, EngineError)| Digest {
        hash: None,
        text,
        err: Some(e),
    };
    for rel in DIGEST_RELATIONS {
        if let Err(e) = digest_fold(s, &format!("SELECT * FROM {q}{rel}"), &mut b, &mut tables) {
            return failed(e);
        }
    }
    tables.sort();
    let mut unused = Vec::new();
    for t in &tables {
        if let Err(e) = digest_fold(s, &format!("SELECT * FROM {q}\"{t}\""), &mut b, &mut unused) {
            return failed(e);
        }
    }
    let hash = format!("{:016x}", fnv(b.as_bytes()));
    Digest {
        hash: Some(hash),
        text: b,
        err: None,
    }
}

/// The logical image — the pages below the high-water — folded into FNV-1a 64 (§8.4). Preallocated
/// tails past the high-water are host policy and excluded.
fn image_hash(image: &[u8], pages: u32, page_size: u32) -> u64 {
    let n = (pages as usize * page_size as usize).min(image.len());
    fnv(&image[..n])
}

/// A key step's target: simulation key 1–3, or -1 for `plain`.
fn target_key(s: &str) -> i32 {
    if s == "plain" {
        -1
    } else {
        s.parse().unwrap_or(0)
    }
}

/// The attachments' check/recovery state as `,"dbs":{"a1":{...},...}`, or "" with none.
fn dbs_json(entries: &[String]) -> String {
    if entries.is_empty() {
        return String::new();
    }
    format!(",\"dbs\":{{{}}}", entries.join(","))
}

impl<'a> Runner<'a> {
    fn new(tr: &'a Trace) -> Runner<'a> {
        let seed: u64 = tr.header("seed").parse().unwrap_or(0);
        let mut ps: i64 = tr.header("page_size").parse().unwrap_or(0);
        if ps == 0 {
            ps = 256;
        }
        let cache: i64 = tr.header("cache_bytes").parse().unwrap_or(0);
        let clock: i64 = tr.header("clock").parse().unwrap_or(0);
        let mut sector: i64 = tr.header("sector").parse().unwrap_or(0);
        if sector <= 0 {
            sector = SECTOR_DEFAULT as i64;
        }
        let work_mem: i64 = tr.header("work_mem").parse().unwrap_or(0);
        let temp_buffers: i64 = tr.header("temp_buffers").parse().unwrap_or(0);
        let max_query_memory: i64 = tr.header("max_query_memory_bytes").parse().unwrap_or(0);
        let max_storage_bytes: i64 = tr.header("max_storage_bytes").parse().unwrap_or(0);
        let clock = Arc::new(AtomicI64::new(clock));
        let random = Arc::new(SimRandom {
            current: Mutex::new(None),
        });
        let encrypted = tr.header("encrypted") == "1";
        let mut fs = SimFs::new(seed, sector as usize, ps as u32);
        fs.archiving = encrypted;
        Runner {
            tr,
            seed,
            page_size: ps as u32,
            cache_bytes: cache,
            clock,
            random,
            work_mem,
            temp_buffers,
            max_query_memory,
            max_storage_bytes,
            relaxed: tr.header("synchronous") == "off",
            flush_interval_ms: tr.header("flush_interval_ms").parse().unwrap_or(0),
            sessions: HashMap::new(),
            db: None,
            service: tr.header("processes") == "service",
            net: SimNet::new(),
            procs: BTreeMap::new(),
            cur: 0,
            locks: None,
            fs: Arc::new(Mutex::new(fs)),
            armed: None,
            transcript: String::new(),
            dbs: BTreeMap::new(),
            violation: String::new(),
            violation_step: -1,
            crash_image: None,
            stack: String::new(),
            last_digest_text: String::new(),
            digest_err: None,
            diagnostics: Vec::new(),
            image_prefix: None,
            backups: 0,
            encrypted,
            opens: 0,
            backups_ok: Vec::new(),
            step_index: 0,
        }
    }

    /// Database `name`'s credential: its simulation key's, or none while it is plaintext.
    fn credential(&self, name: &str) -> Option<&'static Credential> {
        sim_credential(self.dbs[name].key)
    }

    /// The Environment of one opening of process `pid` (or of a create the runner does as a host
    /// would): the shared seeded SQL source and clock, and in an encrypted trace an insecure
    /// key-entropy stream of its own, seeded from lane 14 (§5) by the run's count of openings and
    /// `pid`. The seeded source starts every database's stream afresh from its seed, so a stream
    /// shared by two openings — an owner and its client, or one process before and after a crash —
    /// would draw the same data keys and nonces, which the CSPRNG it models never does
    /// (encryption.md §3).
    fn new_env(&mut self, pid: u32) -> Environment {
        let mut b = Environment::builder()
            .random_source(self.random.clone())
            .clock_source(Arc::new(SimClock(self.clock.clone())));
        if self.encrypted {
            // Seeded so the cores' images stay byte-identical (encrypted.md §8).
            b = b.insecure_seeded_key_entropy(decide(
                self.seed,
                LANE_KEY_SEED,
                self.opens,
                pid as u64,
                0,
            ));
        }
        self.opens += 1;
        b.build()
    }

    /// The Environment the step's process opened with.
    fn proc_env(&self) -> Environment {
        self.procs[&self.cur].env.clone()
    }

    /// Whether simulation key `k` (-1: none) opens `image`: `k` unwraps its key block, or the file is
    /// plaintext and `k` is -1.
    fn sim_unlocks(&self, image: Option<&[u8]>, k: i32) -> bool {
        let ps = self.page_size as usize;
        let Some(image) = image else {
            return false;
        };
        if image.len() < 2 * ps {
            return false;
        }
        let Ok(suite) = crate::crypto::file_suite(&image[..ps], &image[ps..2 * ps]) else {
            return false;
        };
        if k < 0 || suite == 0 {
            return k < 0 && suite == 0;
        }
        if image.len() < 4 * ps {
            return false;
        }
        crate::crypto::unlock(
            &image[2 * ps..3 * ps],
            &image[3 * ps..4 * ps],
            &SIM_KEYS[k as usize],
            crate::seam::os_random_source(),
        )
        .is_ok()
    }

    /// Record the key recovery opened database `name` with.
    fn unlocked(&mut self, i: usize, name: &str) {
        let db_field = if name == "main" {
            String::new()
        } else {
            format!(",\"db\":{}", go_quote(name))
        };
        let key = self.dbs[name].key;
        self.emit(format!(
            "{{\"i\":{i},\"op\":\"unlocked\"{db_field},\"key\":{key}}}"
        ));
    }

    /// After a crash that interrupted a credential change or rekey of `name` (S12): exactly one of
    /// the old and new keys (-1: plaintext, a conversion) opens its file, and the new one when the
    /// step had succeeded (its last barrier ran). The runner continues with whichever opens.
    fn settle_key(&mut self, i: usize, name: &str, image: Option<&[u8]>) -> bool {
        let Some(change) = self.sdb(name).key_change.take() else {
            return self.follow_key(i, name, image);
        };
        let (old, next) = (change.old, change.next);
        let acknowledged = self.dbs[name].key == next;
        let (a, b) = (self.sim_unlocks(image, old), self.sim_unlocks(image, next));
        if old == next && b {
            // A change to the key already in use (a rotation): it still opens.
        } else if old != next && a && !b && !acknowledged {
            self.sdb(name).key = old;
        } else if old != next && !a && b {
            self.sdb(name).key = next;
        } else if change.entry_pending && !a && !b {
            // An older file came back (its rename was never made durable): whichever key opens it.
            return self.follow_key(i, name, image);
        } else if old == next {
            self.fail(i, format!("encryption: key {next} no longer opens {name}"));
            return false;
        } else if a && !b {
            self.fail(
                i,
                format!("durability: the acknowledged change of {name} to key {next} was lost"),
            );
            return false;
        } else {
            self.fail(
                i,
                format!(
                    "encryption: key {old} opens {name}: {a}, key {next}: {b}; want exactly one"
                ),
            );
            return false;
        }
        self.unlocked(i, name);
        true
    }

    /// Recovery outside a key step: a rekey whose rename was not yet durable in its directory may
    /// come back as the older file under its older key (validated-cow.md §3), or plaintext, so the
    /// database opens with whichever simulation key opens the recovered file, the current one first.
    fn follow_key(&mut self, i: usize, name: &str, image: Option<&[u8]>) -> bool {
        if !self.encrypted || image.is_none() {
            return true;
        }
        let current = self.dbs[name].key;
        let order = std::iter::once(current).chain((-1..4).filter(|&k| k != current));
        for k in order {
            if self.sim_unlocks(image, k) {
                if k != current {
                    self.sdb(name).key = k;
                    self.unlocked(i, name);
                }
                return true;
            }
        }
        self.fail(i, format!("encryption: no simulation key opens {name}"));
        false
    }

    /// Forget every database's key step once its step is over.
    fn clear_key_changes(&mut self) {
        for d in self.dbs.values_mut() {
            d.key_change = None;
        }
    }

    /// The key a database is created under: simulation key 0 in an encrypted trace, else none.
    fn create_key(&self) -> i32 {
        if self.encrypted { 0 } else { -1 }
    }

    fn disk(&self) -> std::sync::MutexGuard<'_, SimFs> {
        self.fs.lock().unwrap_or_else(|e| e.into_inner())
    }

    /// Run one of the runner's own oracle reads with read and spill faults suspended: an armed fault
    /// targets the trace's statements, not the oracle checking them.
    fn oracle<T>(&self, f: impl FnOnce() -> T) -> T {
        self.disk().oracle = true;
        let result = f();
        self.disk().oracle = false;
        result
    }

    fn ops(&self) -> u64 {
        self.disk().ops
    }

    fn db(&self) -> &Database {
        self.db.as_ref().expect("a database is open")
    }

    fn fail(&mut self, step: usize, msg: String) {
        if self.violation.is_empty() {
            self.violation = format!("step {step} (line {}): {msg}", self.tr.steps[step].line);
            self.violation_step = step as i64;
        }
    }

    fn emit(&mut self, line: String) {
        self.transcript.push_str(&line);
        self.transcript.push('\n');
    }

    /// The main database's oracle state.
    fn main_db(&self) -> &SimDb {
        &self.dbs["main"]
    }

    fn main_db_mut(&mut self) -> &mut SimDb {
        self.dbs.get_mut("main").expect("main is tracked")
    }

    fn sdb(&mut self, name: &str) -> &mut SimDb {
        self.dbs.get_mut(name).expect("a tracked database")
    }

    /// The attachments the runner tracks, in name order.
    fn attached_names(&self) -> Vec<String> {
        self.dbs.keys().filter(|n| *n != "main").cloned().collect()
    }

    /// Every tracked database: main, then the attachments in name order.
    fn order(&self) -> Vec<String> {
        let mut out = vec!["main".to_string()];
        out.extend(self.attached_names());
        out
    }

    /// Open p0 over the simulated disk through the ordinary demand-paged loader — the path a
    /// reopening process takes, including validated-COW recovery (validated-cow.md §1) — and
    /// re-attach every tracked attachment whose file exists.
    fn open(&mut self) -> Result<(), String> {
        self.open_proc(0).map_err(|e| e.to_string())?;
        if self.service {
            return Ok(()); // open_proc re-attached them
        }
        for name in self.attached_names() {
            let file = self.dbs[&name].file.clone();
            if self.disk().file(&file).is_none() {
                continue; // the caller decides whether losing it was allowed
            }
            if let Err(e) = self.attach(&name) {
                return Err(format!("re-attach {name}: {e}"));
            }
        }
        Ok(())
    }

    /// Attach the existing file of attachment `name` read-write to the current process: under the
    /// page service in a service trace (owner or page client of the file, README.md §6.6),
    /// uncoordinated otherwise.
    fn attach(&self, name: &str) -> Result<(), EngineError> {
        let file = &self.dbs[name].file;
        let locking = if self.service {
            Locking::Auto
        } else {
            Locking::None
        };
        let mut source = AttachSource::file(file).locking(locking);
        if let Some(cred) = self.credential(name) {
            source = source.credential(cred.clone());
        }
        self.db().attach(name, source, false)
    }

    /// Start process `pid`. A service trace elects it through the simulated lock host and network,
    /// exactly as `Database::open_with_options` does through the OS host.
    fn open_proc(&mut self, pid: u32) -> Result<(), EngineError> {
        let env = self.new_env(pid);
        let db = if self.service {
            self.open_service_proc(pid, env.clone())?
        } else {
            let db = Database::from_engine(self.open_engine(&env)?);
            // Create, compaction, and attachments go through the simulated filesystem.
            db.sim_set_files(Arc::new(SimHost(self.fs.clone())));
            // Every flush lands in the step that caused it.
            db.sim_set_relaxed(self.relaxed, true, self.flush_interval_ms);
            if self.max_storage_bytes > 0 {
                db.set_max_storage_bytes("main", self.max_storage_bytes)?;
            }
            db
        };
        self.procs.insert(
            pid,
            Proc {
                db: db.clone(),
                env,
            },
        );
        self.cur = pid;
        self.db = Some(db);
        if self.service {
            // Every process attaches every tracked attachment whose file exists: the owner of the
            // file, or a page client of whichever process owns it (repair_co_ownership made main's
            // owner attach every one first).
            for name in self.attached_names() {
                let file = self.dbs[&name].file.clone();
                if self.disk().file(&file).is_none() {
                    continue;
                }
                if let Err(e) = self.attach(&name) {
                    let _ = self.close_proc(pid);
                    return Err(EngineError::new(
                        e.state,
                        format!("re-attach {name}: {}", e.message),
                    ));
                }
            }
            self.net.settle();
        }
        Ok(())
    }

    /// Open process `pid` under the page service (S8): its own lock host over the shared lock table
    /// and network, the simulated filesystem and spill host, and no background re-election, so a
    /// client re-elects at its next transaction begin, in trace order. Every owner limit that would
    /// start a timer is off.
    fn open_service_proc(&mut self, pid: u32, env: Environment) -> Result<Database, EngineError> {
        let table = self
            .locks
            .get_or_insert_with(|| locks::new_table(self.clock.clone()))
            .clone();
        let host = Arc::new(locks::SimLockHost::new(
            table.clone(),
            pid,
            self.net.clone(),
        ));
        let cache = if self.cache_bytes <= 0 {
            DEFAULT_CACHE_BYTES
        } else {
            self.cache_bytes as usize
        };
        let opts = OpenOptions {
            cache_bytes: cache,
            file_lock_timeout_ms: crate::file::DEFAULT_FILE_LOCK_TIMEOUT_MS,
            idle_in_transaction_timeout_ms: 0,
            idle_session_timeout_ms: Some(0),
            shutdown_grace_ms: Some(SERVICE_GRACE_MS),
            environment: env,
            max_storage_bytes: self.max_storage_bytes,
            credential: self.credential("main").cloned(),
            // Every process seals its scratch files in an encrypted trace, so encrypting a plaintext
            // database is allowed (S13).
            scratch_encryption: if self.encrypted {
                crate::file::ScratchEncryption::On
            } else {
                crate::file::ScratchEncryption::Auto
            },
            synchronous: if self.relaxed {
                crate::file::Synchronous::Off
            } else {
                crate::file::Synchronous::On
            },
            flush_interval_ms: self.flush_interval_ms,
            ..OpenOptions::default()
        };
        let opened = Database::sim_open_service(
            host,
            Arc::new(SimHost(self.fs.clone())),
            Arc::new(SimSpill(self.fs.clone())),
            Path::new(MAIN_FILE),
            opts,
        );
        match opened {
            Ok(db) => {
                db.sim_set_inline_flush(); // every flush lands in the step that caused it
                self.net.settle();
                Ok(db)
            }
            Err(e) => {
                locks::release(&table, pid);
                self.net.kill(pid);
                self.net.settle();
                Err(e)
            }
        }
    }

    /// The running process that owns the main database under the page service.
    fn owner_pid(&self) -> Option<u32> {
        self.owner_pid_of("main")
    }

    /// The running process that owns database `name` under the page service.
    fn owner_pid_of(&self, name: &str) -> Option<u32> {
        self.procs
            .iter()
            .find(|(_, p)| {
                p.db.sim_service_db(name)
                    .is_some_and(|db| db.sim_is_owner())
            })
            .map(|(pid, _)| *pid)
    }

    /// The running processes, in order, that own main or an attachment under the page service.
    fn owner_pids(&self) -> Vec<u32> {
        let order = self.order();
        self.procs
            .iter()
            .filter(|(_, p)| {
                order.iter().any(|name| {
                    p.db.sim_service_db(name)
                        .is_some_and(|db| db.sim_is_owner())
                })
            })
            .map(|(pid, _)| *pid)
            .collect()
    }

    /// Attach file database `name` in every running process of a service trace (README.md §6.6):
    /// main's owner first — so it owns the file too, and one process owns every database — then the
    /// others in process order, each a page client of it. With no owner of main, the lowest
    /// process's read begin first re-elects it. A process that already has it attached is skipped.
    /// It leaves the attaching owner as the step's process.
    fn attach_everywhere(&mut self, i: usize, name: &str) -> bool {
        let first = match self.owner_pid() {
            Some(pid) => pid,
            None => {
                let first = self.live_pids()[0];
                self.select_proc(first);
                let d = self.committed_digest("main");
                let v = self.db().version();
                if !self.observe(i, &format!("attaching p{first}"), v, d) {
                    return false;
                }
                self.net.settle();
                first
            }
        };
        let mut order = vec![first];
        order.extend(self.live_pids().into_iter().filter(|pid| *pid != first));
        for pid in order {
            self.select_proc(pid);
            if self.db().sim_has_attachment(name) {
                continue;
            }
            let result = self.attach(name);
            self.net.settle();
            if let Err(e) = result {
                self.select_proc(first);
                self.attach_failed(i, name, e);
                return false;
            }
        }
        self.select_proc(first);
        true
    }

    /// Whether every running process has attachment `name` attached.
    fn attached_in_all(&self, name: &str) -> bool {
        self.procs.values().all(|p| p.db.sim_has_attachment(name))
    }

    /// Load the engine over the simulated main file.
    fn open_engine(&self, env: &Environment) -> Result<Engine, EngineError> {
        let Some(main) = self.disk().file(MAIN_FILE) else {
            return Err(EngineError::new(
                crate::error::SqlState::IoError,
                "the database file is gone",
            ));
        };
        let pager = Pager::from_store(Box::new(SimStore {
            fs: self.fs.clone(),
            file: main,
        }))?;
        let cache = if self.cache_bytes <= 0 {
            DEFAULT_CACHE_BYTES
        } else {
            self.cache_bytes as usize
        };
        let page_size = pager.page_size();
        let mut engine = Engine::open_paged(
            pager,
            cache_leaves(cache, page_size),
            env,
            self.credential("main"),
        )?;
        // The path marks the engine durable; the simulated filesystem is its only storage.
        engine.path = Some(PathBuf::from(MAIN_FILE));
        // A writable open finishes a credential change a crash interrupted (encrypted.md §5).
        engine.repair_key_block()?;
        // Spill and temp-table spill scratch files, whose operations can fail; sealed in an
        // encrypted trace (encryption.md §6), whatever main is now, so encrypting a plaintext
        // database is allowed (S13).
        engine.spill = Some(crate::file::seal_scratch(
            Arc::new(SimSpill(self.fs.clone())),
            self.encrypted,
            env,
        ));
        Ok(engine)
    }

    /// Tell the lock table which processes hold an open write session: a real probe would wait for
    /// that writer to finish, so the simulation does not run it.
    fn sessions_changed(&self) {
        if let Some(table) = &self.locks {
            let busy: BTreeSet<u32> = self
                .sessions
                .values()
                .filter(|ss| ss.write)
                .map(|ss| ss.pid)
                .collect();
            locks::set_busy(table, busy);
        }
    }

    /// The running processes, in order.
    fn live_pids(&self) -> Vec<u32> {
        self.procs.keys().copied().collect()
    }

    /// `pid`'s open sessions, in name order.
    fn sessions_of(&self, pid: u32) -> Vec<String> {
        let mut sids: Vec<String> = self
            .sessions
            .iter()
            .filter(|(_, ss)| ss.pid == pid)
            .map(|(sid, _)| sid.clone())
            .collect();
        sids.sort();
        sids
    }

    /// End process `pid` cleanly: its sessions end (a writer rolls back) and its Database closes,
    /// releasing its locks.
    fn close_proc(&mut self, pid: u32) -> Result<(), EngineError> {
        for sid in self.sessions_of(pid) {
            let mut ss = self.sessions.remove(&sid).expect("a listed session exists");
            if ss.write {
                let _ = ss.s.rollback();
            } else {
                ss.s.close();
            }
        }
        self.sessions_changed();
        let proc = self.procs.remove(&pid).expect("a running process");
        if self.cur == pid {
            self.db = None;
        }
        let result = proc.db.close();
        if let Some(table) = &self.locks {
            locks::release(table, pid);
        }
        if self.service {
            self.net.kill(pid);
            self.net.settle();
        }
        result
    }

    /// Abandon process `pid` as a crash does: its sessions and Database vanish without closing, and
    /// the kernel releases its locks.
    ///
    /// Under the page service a dead process does nothing more — no rollback frame, no release of
    /// ownership, no removal of its owner record — so its sessions and Database are leaked rather
    /// than dropped (a drop would end its page-service role cleanly), and the network closes its
    /// listener and connections, as the kernel closes a dead process's sockets.
    fn drop_proc(&mut self, pid: u32) {
        if let Some(p) = self.procs.get(&pid) {
            // A dead owner may take every version above the floor with it (§8.2): under
            // synchronous = off the simulated process crash may drop writes of the step that
            // acknowledged a commit, and under either mode a generation it adopted but never
            // stabilized (validated-cow.md §3) may be dropped by a failed stabilization sync. Each
            // database it owned (main or an attachment under the service) has its own floor.
            let owned: Vec<String> = self
                .dbs
                .keys()
                .filter(|name| {
                    p.db.sim_service_db(name)
                        .is_some_and(|db| db.sim_is_owner())
                })
                .cloned()
                .collect();
            for name in owned {
                self.sdb(&name).owner_lost = true;
            }
        }
        for sid in self.sessions_of(pid) {
            let ss = self.sessions.remove(&sid);
            if self.service {
                std::mem::forget(ss);
            }
        }
        self.sessions_changed();
        if let Some(table) = &self.locks {
            locks::release(table, pid);
        }
        let proc = self.procs.remove(&pid);
        if self.cur == pid {
            self.db = None;
        }
        if self.service {
            std::mem::forget(proc);
            self.net.kill(pid);
            self.net.settle();
        }
    }

    /// Check the version and contents a process sees of main when it begins (S5): in a shared trace
    /// another process may have committed — or died mid-commit, leaving a complete generation
    /// another process adopts — so the version may be newer than the last this runner saw, but never
    /// older, and its contents must be a generation the history records.
    fn observe(&mut self, i: usize, who: &str, v: u64, d: Option<String>) -> bool {
        self.observe_db(i, "main", who, v, d)
    }

    /// [`observe`](Self::observe) for database `name`: under the page service every attachment is
    /// shared too.
    fn observe_db(&mut self, i: usize, name: &str, who: &str, v: u64, d: Option<String>) -> bool {
        let what = if name == "main" {
            String::new()
        } else {
            format!(" of {name}")
        };
        let m = &self.dbs[name];
        let msg = match &d {
            None => Some(format!(
                "{who}: version {v}{what} is unreadable: {}",
                self.digest_err
                    .as_ref()
                    .map_or("<nil>".to_string(), |e| e.to_string())
            )),
            Some(_) if v < m.version && (!m.owner_lost || v < m.floor) => Some(format!(
                "{who} sees version {v}{what} after version {} was published",
                m.version
            )),
            Some(_) if v > m.max_attempted => Some(format!(
                "{who} sees version {v}{what}, which was never attempted (latest attempted {})",
                m.max_attempted
            )),
            Some(d) if !m.in_history(v, d) => Some(format!(
                "{who} sees version {v}{what} with contents (digest {d}) no transaction produced"
            )),
            Some(_) => None,
        };
        if let Some(msg) = msg {
            self.fail(i, msg);
            return false;
        }
        let m = self.sdb(name);
        m.version = v;
        m.last_digest = d.expect("checked above");
        m.owner_lost = false;
        true
    }

    /// Make `pid` the process running the step.
    fn select_proc(&mut self, pid: u32) -> bool {
        let Some(p) = self.procs.get(&pid) else {
            return false;
        };
        self.db = Some(p.db.clone());
        self.cur = pid;
        true
    }

    /// The process a step runs in: a session's own, an explicit one, or the lowest running.
    fn step_pid(&self, st: &Step) -> Option<u32> {
        match st.kind.as_str() {
            "open" | "spawn" | "exit" | "kill" => Some(st.pid),
            "backup" if st.has_pid => Some(st.pid),
            "on" | "commit" | "rollback" | "close" => self.sessions.get(&st.sid).map(|ss| ss.pid),
            _ => self.procs.keys().next().copied(),
        }
    }

    /// Start a process (S5) and check what it sees.
    fn step_spawn(&mut self, i: usize, pid: u32) {
        if self.procs.contains_key(&pid) {
            // The generator cannot know a fault killed the owner and that p0 restarted since.
            self.emit(format!(
                "{{\"i\":{i},\"op\":\"spawn\",\"pid\":{pid},\"skip\":true}}"
            ));
            return;
        }
        if let Err(e) = self.open_proc(pid) {
            let code = engine_code(&e);
            if code == "XX001" {
                self.fail(i, format!("spawn p{pid}: {e}"));
                return;
            }
            self.emit(format!(
                "{{\"i\":{i},\"op\":\"spawn\",\"pid\":{pid},\"error\":{}}}",
                go_quote(&code)
            ));
            return;
        }
        let v = self.db().version();
        let d = self.committed_digest("main");
        if !self.observe(i, &format!("spawned p{pid}"), v, d) {
            return;
        }
        let mut versions: HashMap<String, u64> = HashMap::new();
        for name in self.attached_names() {
            if self.db_version(&name) == 0 {
                continue;
            }
            let ad = self.committed_digest(&name);
            let av = self.db_version(&name);
            if !self.observe_db(i, &name, &format!("spawned p{pid}"), av, ad) {
                return;
            }
            versions.insert(name.clone(), self.db_version(&name));
        }
        let dbs = self.versions_json(&versions);
        self.emit(format!(
            "{{\"i\":{i},\"op\":\"spawn\",\"pid\":{pid},\"version\":{v}{dbs}}}"
        ));
    }

    /// The version of database `name` the current process has published.
    fn db_version(&self, name: &str) -> u64 {
        if name == "main" {
            return self.db().version();
        }
        self.db().sim_attached_version(name).unwrap_or(0)
    }

    /// The attachments' versions as `,"dbs":{"a1":V,...}`, or "" with none, so a trace without
    /// attachments keeps its transcript shape.
    fn versions_json(&self, versions: &HashMap<String, u64>) -> String {
        let names = self.attached_names();
        if names.is_empty() {
            return String::new();
        }
        let entries: Vec<String> = names
            .iter()
            .filter_map(|name| {
                versions
                    .get(name)
                    .map(|v| format!("{}:{v}", go_quote(name)))
            })
            .collect();
        format!(",\"dbs\":{{{}}}", entries.join(","))
    }

    /// The digest of what `s` sees of database `name`, as an oracle read.
    fn digest_of(&mut self, s: &mut Session, name: &str) -> Option<String> {
        let d = self.oracle(|| digest(s, name));
        self.last_digest_text = d.text;
        self.digest_err = d.err;
        d.hash
    }

    /// The version and digest of database `name` a fresh read session sees.
    fn committed_view(&mut self, name: &str) -> (u64, Option<String>) {
        let d = self.committed_digest(name);
        (self.db_version(name), d)
    }

    fn committed_digest(&mut self, name: &str) -> Option<String> {
        let mut rs = self.db().read_session();
        let mut d = self.digest_of(&mut rs, name);
        rs.close();
        if d.is_none() && self.reopen_stale() {
            let mut rs = self.db().read_session();
            d = self.digest_of(&mut rs, name);
            rs.close();
        }
        d
    }

    /// Whether the digest that just failed found the process's data key stale (S13): a page client
    /// of a database rekeyed, decrypted, or encrypted since it opened is told to reopen (28P04, or
    /// 28P02 for a plaintext client — encrypted.md §14).
    fn key_stale(&self) -> Option<String> {
        if !self.service || !self.encrypted {
            return None;
        }
        let code = engine_code(self.digest_err.as_ref()?);
        (code == "28P04" || code == "28P02").then_some(code)
    }

    /// Restart the step's process when [`key_stale`](Self::key_stale): the host reopens it with the
    /// database's current key, and its sessions end. Whether it did, so the caller reads again.
    fn reopen_stale(&mut self) -> bool {
        if self.key_stale().is_none() {
            return false;
        }
        let pid = self.cur;
        let step = self.step_index;
        if let Err(e) = self.close_proc(pid) {
            self.fail(step, format!("reopen p{pid} after a stale key: {e}"));
            return false;
        }
        if let Err(e) = self.open_proc(pid) {
            self.fail(step, format!("reopen p{pid} after a stale key: {e}"));
            return false;
        }
        self.emit(format!(
            "{{\"i\":{step},\"op\":\"reopened\",\"pid\":{pid}}}"
        ));
        true
    }

    /// The image of database `name`'s file — what a new process would open — or `None` if it is
    /// gone.
    fn image(&self, name: &str) -> Option<Vec<u8>> {
        let file = self.dbs[name].file.clone();
        self.disk().image(&file)
    }

    /// Whether the commit being checked ran with nothing that may hold reclamation back: no other
    /// session (a reader pins its snapshot), no other process (co-resident commits are append-only),
    /// and no fault.
    fn quiet(&self) -> bool {
        !self.service && self.sessions.is_empty() && !self.disk().armed()
    }

    fn run(&mut self) {
        let processes = self.tr.header("processes");
        if !processes.is_empty() && processes != "service" {
            self.violation = format!("unsupported processes mode {processes}");
            return;
        }
        // Create the database through the simulated filesystem, as the host's create does: a temp
        // file, its sync, the rename, and the directory barrier (S4).
        let mut m = SimDb::new(MAIN_FILE);
        m.key = self.create_key();
        let env = self.new_env(0);
        let created = Engine::create_via(
            &SimHost(self.fs.clone()),
            Path::new(MAIN_FILE),
            DatabaseOptions {
                page_size: self.page_size,
                no_sync: false,
            },
            sim_credential(m.key).map(|credential| crate::file::Encryption {
                credential,
                kdf: crate::crypto::Argon2Params::default(),
                environment: &env,
            }),
        );
        match created {
            Ok(e) => {
                let _ = e.close();
            }
            Err(e) => {
                self.violation = format!("create: {e}");
                return;
            }
        }
        self.dbs.insert("main".to_string(), m);
        if let Err(e) = self.open() {
            self.violation = format!("initial open: {e}");
            return;
        }
        let v = self.db().version();
        {
            let m = self.main_db_mut();
            m.version = v;
            m.floor = v;
            m.max_attempted = v;
        }
        let Some(d) = self.committed_digest("main") else {
            self.violation = "initial digest failed".to_string();
            return;
        };
        let m = self.main_db_mut();
        m.last_digest = d.clone();
        m.add_history(v, d);
        self.observe_growth("main");
        for i in 0..self.tr.steps.len() {
            if !self.step(i) || !self.violation.is_empty() {
                return;
            }
        }
    }

    /// Run one trace step; false stops the run. A panic anywhere is a violation.
    fn step(&mut self, i: usize) -> bool {
        let outcome = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| self.step_inner(i)));
        match outcome {
            Ok(cont) => cont,
            Err(payload) => {
                let msg = if let Some(s) = payload.downcast_ref::<&str>() {
                    s.to_string()
                } else if let Some(s) = payload.downcast_ref::<String>() {
                    s.clone()
                } else {
                    "unknown panic".to_string()
                };
                self.fail(i, format!("panic: {msg}"));
                self.stack =
                    std::mem::take(&mut *LAST_PANIC.lock().unwrap_or_else(|e| e.into_inner()));
                false
            }
        }
    }

    fn step_inner(&mut self, i: usize) -> bool {
        let tr = self.tr;
        let st = &tr.steps[i];
        self.step_index = i;
        // Draws during this step come from the stream of the session it runs on (none for a step
        // on no open session).
        *self
            .random
            .current
            .lock()
            .unwrap_or_else(|e| e.into_inner()) =
            self.sessions.get(&st.sid).map(|ss| ss.random.clone());
        match st.kind.as_str() {
            "fault" => {
                let f = match fault_of(st) {
                    Ok(f) => f,
                    Err(e) => {
                        self.fail(i, e);
                        return false;
                    }
                };
                self.armed = Some(f);
                self.emit(format!(
                    "{{\"i\":{i},\"op\":\"fault\",\"kind\":{}}}",
                    go_quote(&st.mode)
                ));
                return true;
            }
            "crash" => {
                {
                    let mut disk = self.disk();
                    disk.begin_step(i as u64, None);
                    if st.mode == "power" {
                        disk.power_loss(i as u64, st.int_param("survive"), st.int_param("tear"));
                    }
                }
                return self.recover(i, "none");
            }
            "clock" => {
                let delta: i64 = st
                    .params
                    .get("delta")
                    .and_then(|d| d.parse().ok())
                    .unwrap_or(0);
                self.clock.fetch_add(delta, Ordering::Relaxed);
                self.emit(format!("{{\"i\":{i},\"op\":\"clock\"}}"));
                return true;
            }
            "tick" => {
                self.emit(format!("{{\"i\":{i},\"op\":\"tick\"}}"));
                return true;
            }
            "disconnect" => {
                // The process's connection to the owner ends (S8): both ends see end of stream.
                let pid = st.pid;
                let client = self.procs.get(&pid).and_then(|p| p.db.sim_page_client());
                let Some(client) = client else {
                    self.emit(format!(
                        "{{\"i\":{i},\"op\":\"disconnect\",\"pid\":{pid},\"skip\":true}}"
                    ));
                    return true;
                };
                drop(client);
                self.net.disconnect(pid, Path::new(MAIN_FILE));
                self.net.settle();
                self.emit(format!("{{\"i\":{i},\"op\":\"disconnect\",\"pid\":{pid}}}"));
                return true;
            }
            "exit" => {
                let pid = st.pid;
                if !self.procs.contains_key(&pid) {
                    self.emit(format!(
                        "{{\"i\":{i},\"op\":\"exit\",\"pid\":{pid},\"skip\":true}}"
                    ));
                    return true;
                }
                if let Err(e) = self.close_proc(pid) {
                    self.fail(i, format!("exit p{pid}: {e}"));
                    return false;
                }
                self.emit(format!("{{\"i\":{i},\"op\":\"exit\",\"pid\":{pid}}}"));
                return true;
            }
            "kill" => {
                let pid = st.pid;
                if !self.procs.contains_key(&pid) {
                    self.emit(format!(
                        "{{\"i\":{i},\"op\":\"kill\",\"pid\":{pid},\"skip\":true}}"
                    ));
                    return true;
                }
                self.drop_proc(pid);
                if self.procs.is_empty() {
                    self.disk().begin_step(i as u64, None);
                    return self.recover(i, "none");
                }
                self.emit(format!("{{\"i\":{i},\"op\":\"kill\",\"pid\":{pid}}}"));
                return true;
            }
            "corrupt" => {
                self.disk().begin_step(i as u64, None);
                return self.step_corrupt(i, st);
            }
            "replay" => {
                self.disk().begin_step(i as u64, None);
                return self.step_replay(i, &st.mode);
            }
            "restore" => {
                self.disk().begin_step(i as u64, None);
                return self.step_restore(i, st.int_param("j"));
            }
            _ => {}
        }

        // A step that needs a process when none is running (the last one exited) restarts p0 first.
        if self.procs.is_empty() && st.kind != "spawn" {
            self.disk().begin_step(i as u64, None);
            self.step_spawn(i, 0);
            if !self.violation.is_empty() || self.procs.is_empty() {
                if self.violation.is_empty() {
                    self.fail(i, "p0 could not restart".to_string());
                }
                return false;
            }
        }
        let armed = self.armed.take();
        let start: HashMap<String, u64> = self
            .dbs
            .iter()
            .map(|(name, d)| (name.clone(), d.version))
            .collect();
        let now = self.clock.load(Ordering::Relaxed);
        let timed = self.flush_interval_ms > 0;
        for name in self.order() {
            let open = self.relaxed && !self.engine_flushed(&name);
            let pending = self.relaxed && self.engine_pending(&name);
            let d = self.sdb(&name);
            // A batch past its deadline is flushed by the step's commit before it plans
            // (validated-cow.md §4.1), so that commit plans with nothing pending.
            let due = pending && timed && now >= d.deadline;
            d.batch_open = open && !due;
            d.batch_pending = pending && !due;
            d.due = due;
        }
        if let Some(pid) = self.step_pid(st)
            && st.kind != "spawn"
            && !self.select_proc(pid)
        {
            if st.kind == "open" {
                self.emit(format!(
                    "{{\"i\":{i},\"op\":\"open\",\"sid\":{},\"skip\":true}}",
                    go_quote(&st.sid)
                ));
                return true;
            }
            if st.kind == "backup" {
                self.emit(format!(
                    "{{\"i\":{i},\"op\":\"backup\",\"pid\":{},\"skip\":true}}",
                    st.pid
                ));
                return true;
            }
            if self.procs.is_empty() {
                self.fail(i, "no process is running".to_string());
                return false;
            }
        }
        let disk_fault = match armed {
            Some(f) if f.kind == FaultKind::Disconnect => {
                self.net.begin_step(f.nth);
                None
            }
            other => {
                self.net.begin_step(0);
                other
            }
        };
        self.disk().begin_step(i as u64, disk_fault);
        match st.kind.as_str() {
            "spawn" => self.step_spawn(i, st.pid),
            "open" => self.step_open(i, st),
            "on" => self.step_on(i, st),
            "commit" => self.step_commit(i, st),
            "rollback" | "close" => self.step_end(i, st),
            "check" => self.step_check(i),
            "compact" => self.step_compact(i, &st.sid, None),
            "rekey" => self.step_rekey(i, &st.sid, target_key(&st.mode)),
            "change_key" => self.step_change_key(i, &st.sid, target_key(&st.mode)),
            "backup" => self.step_backup(i, st),
            "attach" => self.step_attach(i, &st.sid),
            "reopen" => {
                if !self.step_reopen(i) {
                    return false;
                }
            }
            _ => {}
        }
        if self.service {
            self.net.settle();
        }
        if !self.violation.is_empty() {
            return false;
        }
        // A completed barrier made every earlier write durable: the generation a database published
        // when the step began can no longer be lost (§8.2).
        // The engine's flush claims, read before the disk lock is taken.
        let flushed: HashMap<String, bool> = if self.relaxed {
            self.order()
                .into_iter()
                .map(|name| {
                    let f = self.engine_flushed(&name);
                    (name, f)
                })
                .collect()
        } else {
            HashMap::new()
        };
        {
            let relaxed = self.relaxed;
            let disk = self.fs.lock().unwrap_or_else(|e| e.into_inner());
            let mut violation = None;
            for (name, d) in self.dbs.iter_mut() {
                let began = start.get(name).copied().unwrap_or(0);
                let Some(id) = disk.file(&d.file) else {
                    continue;
                };
                // Under synchronous = off a barrier proves the step's starting version durable only
                // when the engine was not batching then: a pending version may be durable by
                // accident (a file growth is a full fsync) and still be overwritten by the next
                // commit of its batch (validated-cow.md §4).
                // A commit past its batch's deadline flushes before it plans (validated-cow.md §4.1).
                if d.due
                    && d.version > began
                    && !disk.dead()
                    && disk.fired.is_empty()
                    && !disk.barrier_ok(id)
                {
                    violation = Some(format!(
                        "time-based flush: version {} of {name} committed past its batch's deadline without a flush",
                        d.version
                    ));
                    break;
                }
                if disk.barrier_ok(id) && !d.batch_open && began > d.floor {
                    d.floor = began;
                }
                if !relaxed
                    || disk.dead()
                    || !disk.fired.is_empty()
                    || d.version <= d.floor
                    || !flushed.get(name).copied().unwrap_or(false)
                    || !disk.entry_durable(&d.file)
                {
                    continue;
                }
                // The engine holds nothing pending: it treats the published version as flushed, and
                // will overwrite only the other slot. Hold it to that, after checking the claim
                // against the disk. Its directory entry must be durable too: a process that died
                // between compaction's rename and its directory barrier leaves the new file
                // readable, and a power loss before the next opener's first commit syncs the
                // directory brings the older file back (validated-cow.md §3).
                if disk.meta_pending(id) {
                    violation = Some(format!(
                        "durability: the engine treats version {} of {name} as flushed, but no barrier covered its meta",
                        d.version
                    ));
                    break;
                }
                d.floor = d.version;
            }
            drop(disk);
            if let Some(msg) = violation {
                self.fail(i, msg);
                return false;
            }
        }
        // Checked against the floor this step leaves (a flush in the step moved it).
        for name in self.order() {
            if !self.check_truncated(i, &name) {
                return false;
            }
        }
        // A batch this step started ends at the step's clock plus the interval (validated-cow.md §4.1).
        if self.relaxed && timed {
            let interval =
                i64::try_from(self.flush_interval_ms.saturating_mul(1_000)).unwrap_or(i64::MAX);
            for name in self.order() {
                // A batch starts in a step that began with nothing pending, or whose commit flushed
                // a batch past its deadline.
                let d = &self.dbs[&name];
                let started = if d.due {
                    d.version > start.get(&name).copied().unwrap_or(0)
                } else {
                    !d.batch_pending
                };
                if started && self.engine_pending(&name) {
                    self.sdb(&name).deadline = now.saturating_add(interval);
                }
            }
        }
        let Some(armed) = armed else {
            self.clear_key_changes();
            return true;
        };
        if armed.kind == FaultKind::Disconnect {
            self.clear_key_changes();
            // A lost connection ends no process: its client re-elects at its next begin.
            let fired = if self.net.disconnected() {
                "frame"
            } else {
                "end"
            };
            self.emit(format!(
                "{{\"i\":{i},\"op\":\"disconnected\",\"fired\":{}}}",
                go_quote(fired)
            ));
            return true;
        }
        // Every faulted step ends the process; a power loss also discards the unsynced writes (§5).
        let fired = {
            let disk = self.disk();
            let fired = if disk.fired.is_empty() {
                "end"
            } else {
                disk.fired
            };
            fired
        };
        if armed.kind == FaultKind::PowerLoss {
            self.disk().power_loss(i as u64, armed.survive, armed.tear);
            return self.recover(i, fired);
        }
        // In a service trace any other fault kills the owner, the only process that touches the file,
        // whichever process's step drove its I/O; the others keep running over the same kernel state.
        if self.service && self.procs.len() > 1 {
            // Every owner — of main or of an attachment — is a process that may have touched a file
            // after the fault fired, so each dies; with attachments owned elsewhere that may be more
            // than one.
            let mut pids = self.owner_pids();
            if pids.is_empty() {
                pids = vec![self.cur];
            }
            if pids.len() < self.procs.len() {
                for pid in &pids {
                    self.drop_proc(*pid);
                }
                self.disk().process_death();
                for pid in &pids {
                    self.emit(format!(
                        "{{\"i\":{i},\"op\":\"killed\",\"pid\":{pid},\"fired\":{}}}",
                        go_quote(fired)
                    ));
                }
                // The survivors run on: a key step the dead owner interrupted is settled on the
                // kernel's view of each file, which the next opener reads.
                for name in self.order() {
                    if self.dbs[&name].key_change.is_none() {
                        continue;
                    }
                    let Some(image) = self.image(&name) else {
                        continue;
                    };
                    if !self.settle_key(i, &name, Some(&image)) {
                        return false;
                    }
                }
                return true;
            }
        }
        self.recover(i, fired)
    }

    fn step_open(&mut self, i: usize, st: &Step) {
        if self.sessions.contains_key(&st.sid) {
            self.fail(i, format!("session {} already open", st.sid));
            return;
        }
        let mut s = match st.mode.as_str() {
            "read" => self.db().read_session(),
            "write" => {
                let mut writers: Vec<&String> = self
                    .sessions
                    .iter()
                    .filter(|(_, ss)| ss.write)
                    .map(|(sid, _)| sid)
                    .collect();
                writers.sort();
                if let Some(sid) = writers.first() {
                    let msg = format!("open {} write while {} holds the writer gate", st.sid, sid);
                    self.fail(i, msg);
                    return;
                }
                self.db().write_session()
            }
            other => {
                self.fail(i, format!("unknown session mode {}", go_quote(other)));
                return;
            }
        };
        let random = seeded_random_source(decide(self.seed, LANE_SESSION, i as u64, 0, 0));
        if self.work_mem > 0 {
            s.set_work_mem(self.work_mem as usize);
        }
        if self.temp_buffers > 0 {
            s.set_temp_buffers(self.temp_buffers as usize);
        }
        if self.max_query_memory > 0 {
            s.set_max_query_memory_bytes(self.max_query_memory);
        }
        if self.service {
            // A session that finds its process's data key stale fails to open, and the host reopens
            // the process (reopen_stale).
            let d = self.digest_of(&mut s, "main");
            if d.is_none()
                && let Some(code) = self.key_stale()
            {
                self.stale_open(i, st, s, &code);
                return;
            }
            let v = s.version();
            if !self.observe(i, &format!("session {}", st.sid), v, d) {
                return;
            }
            for name in self.attached_names() {
                let v = s.sim_attached_version(&name);
                if v == 0 {
                    continue;
                }
                let d = self.digest_of(&mut s, &name);
                if d.is_none()
                    && let Some(code) = self.key_stale()
                {
                    self.stale_open(i, st, s, &code);
                    return;
                }
                if !self.observe_db(i, &name, &format!("session {}", st.sid), v, d) {
                    return;
                }
            }
        }
        // A session pins every database's committed root when it opens.
        let version = s.version();
        let mut pins: HashMap<String, u64> = HashMap::new();
        pins.insert("main".to_string(), version);
        for name in self.attached_names() {
            let v = s.sim_attached_version(&name);
            if v != 0 {
                pins.insert(name, v);
            }
        }
        let dbs = self.versions_json(&pins);
        self.sessions.insert(
            st.sid.clone(),
            SimSession {
                s,
                random,
                write: st.mode == "write",
                pins,
                pid: self.cur,
            },
        );
        self.sessions_changed();
        self.emit(format!(
            "{{\"i\":{i},\"op\":\"open\",\"sid\":{},\"version\":{version}{dbs}}}",
            go_quote(&st.sid)
        ));
    }

    /// A session that found its process's data key stale: it ends, the open records the error, and
    /// the host reopens the process.
    fn stale_open(&mut self, i: usize, st: &Step, mut s: Session, code: &str) {
        if st.mode == "write" {
            let _ = s.rollback();
        } else {
            s.close();
        }
        self.emit(format!(
            "{{\"i\":{i},\"op\":\"open\",\"sid\":{},\"error\":{}}}",
            go_quote(&st.sid),
            go_quote(code)
        ));
        self.reopen_stale();
    }

    fn step_on(&mut self, i: usize, st: &Step) {
        let sid = go_quote(&st.sid);
        let Some(ss) = self.sessions.get_mut(&st.sid) else {
            self.emit(format!(
                "{{\"i\":{i},\"op\":\"on\",\"sid\":{sid},\"skip\":true}}"
            ));
            return;
        };
        match sim_query(&mut ss.s, &st.sql) {
            Err(e) => {
                let code = engine_code(&e);
                self.emit(format!(
                    "{{\"i\":{i},\"op\":\"on\",\"sid\":{sid},\"error\":{}}}",
                    go_quote(&code)
                ));
                if code == "XX001" {
                    self.fail(i, format!("corruption: a statement reported XX001: {e}"));
                }
            }
            Ok((n, affected, hash, cost)) => {
                self.emit(format!(
                    "{{\"i\":{i},\"op\":\"on\",\"sid\":{sid},\"rows\":{n},\"affected\":{affected},\"hash\":\"{hash:016x}\",\"cost\":{cost}}}"
                ));
            }
        }
    }

    fn check_live(&self) -> Result<(), String> {
        if self.db().sim_page_client().is_some() {
            // A page client reads pages only under a pinned transaction; its trees are the owner's
            // pages, which the owner's own live check covers.
            return Ok(());
        }
        self.oracle(|| check::check_live(self.db()))
    }

    fn step_commit(&mut self, i: usize, st: &Step) {
        let sid = go_quote(&st.sid);
        let Some(mut ss) = self.sessions.remove(&st.sid) else {
            self.emit(format!(
                "{{\"i\":{i},\"op\":\"commit\",\"sid\":{sid},\"skip\":true}}"
            ));
            return;
        };
        self.sessions_changed();
        let dbs = self.order();
        // What the transaction saw of each database before commit: (digest, text). A database
        // attached after this session opened is skipped: it cannot have written it.
        let mut before: Vec<(Option<String>, String)> = Vec::with_capacity(dbs.len());
        for name in &dbs {
            if !ss.pins.contains_key(name) {
                before.push((None, String::new()));
                continue;
            }
            let d = self.digest_of(&mut ss.s, name);
            before.push((d, self.last_digest_text.clone()));
        }
        let result = ss.s.commit();
        if let Err(e) = result {
            let code = engine_code(&e);
            self.emit(format!(
                "{{\"i\":{i},\"op\":\"commit\",\"sid\":{sid},\"error\":{}}}",
                go_quote(&code)
            ));
            if code == "XX001" {
                self.fail(i, format!("corruption: commit reported XX001: {e}"));
                return;
            }
            for (k, name) in dbs.iter().enumerate() {
                if !ss.pins.contains_key(name) {
                    continue;
                }
                let now = self.db_version(name);
                let (version, file) = {
                    let d = &self.dbs[name];
                    (d.version, d.file.clone())
                };
                if now != version {
                    self.fail(
                        i,
                        format!(
                            "a failed commit published version {now} of {name} (was {version})"
                        ),
                    );
                    return;
                }
                // The commit reached storage, so a crash may still recover its generation (§8.1).
                let wrote = {
                    let disk = self.disk();
                    disk.file(&file).is_some_and(|id| disk.file_writes(id) > 0)
                };
                if let (true, Some(inflight)) = (wrote, before[k].0.clone()) {
                    let d = self.sdb(name);
                    d.add_history(version + 1, inflight);
                    d.max_attempted = d.max_attempted.max(version + 1);
                }
            }
            return;
        }
        let versions: HashMap<String, u64> = dbs
            .iter()
            .map(|name| (name.clone(), self.db_version(name)))
            .collect();
        let main_version = versions["main"];
        let dbs_field = self.versions_json(&versions);
        let role = if !self.service {
            ""
        } else if self.db().sim_page_client().is_some() {
            ",\"role\":\"client\""
        } else {
            ",\"role\":\"owner\""
        };
        self.emit(format!(
            "{{\"i\":{i},\"op\":\"commit\",\"sid\":{sid},\"version\":{main_version}{dbs_field}{role}}}"
        ));
        let quiet = self.quiet();
        for (k, name) in dbs.iter().enumerate() {
            if !ss.pins.contains_key(name) {
                continue; // not attached in this session's process when it opened: it cannot have written it
            }
            let (base, last_digest) = {
                let d = &self.dbs[name];
                (d.version, d.last_digest.clone())
            };
            let now = versions[name];
            let (inflight, inflight_text) = before[k].clone();
            if now == base {
                if let Some(inflight) = &inflight
                    && *inflight != last_digest
                {
                    self.fail(
                        i,
                        format!(
                            "commit succeeded without publishing the transaction's changes to {name}"
                        ),
                    );
                    return;
                }
            } else if now == base + 1 {
                let Some(inflight) = inflight else {
                    self.fail(
                        i,
                        format!(
                            "commit published version {now} of {name} from a transaction whose reads failed"
                        ),
                    );
                    return;
                };
                let mut published = self.committed_digest(name);
                if published.is_none() && self.relaxed && !self.disk().fired.is_empty() {
                    // The batch cap's flush failed in this step and revoked the storage, so nothing
                    // can be read back; the acknowledged commit is checked by the recovery that
                    // follows.
                    published = Some(inflight.clone());
                }
                if published.is_none()
                    && self.service
                    && !self.disk().dead()
                    && self.digest_err.as_ref().map(engine_code).as_deref() == Some("08006")
                {
                    // An armed disconnect landed in the read-back's own frames: read it again,
                    // re-electing first.
                    published = self.committed_digest(name);
                }
                if published.is_none() && self.service && self.disk().dead() {
                    // The owner died later in this step (its maintenance commit hit the fault), so
                    // nothing can be read back through it; the acknowledged commit is checked by the
                    // recovery that follows.
                    published = Some(inflight.clone());
                }
                if published.as_deref() != Some(inflight.as_str()) {
                    self.diagnostics = vec![
                        ("before-commit.txt".to_string(), inflight_text),
                        (
                            "after-commit.txt".to_string(),
                            self.last_digest_text.clone(),
                        ),
                    ];
                    self.fail(
                        i,
                        format!(
                            "version {now} of {name} does not contain what its transaction saw before commit"
                        ),
                    );
                    return;
                }
                let relaxed = self.relaxed;
                let d = self.sdb(name);
                d.add_history(now, inflight.clone());
                d.version = now;
                d.last_digest = inflight.clone();
                d.max_attempted = d.max_attempted.max(now);
                if !relaxed {
                    d.floor = now; // acknowledged under synchronous = on; a relaxed client's joins the owner's batch (§8.2)
                }
                // A page client planned against the owner's batch at its begin_write, which is where
                // the owner flushes a batch past its deadline (validated-cow.md §4.1): its commit
                // joins the batch, however late.
                let client = self
                    .db()
                    .sim_service_db(name)
                    .is_some_and(|db| db.sim_page_client().is_some());
                let d = self.sdb(name);
                if client && d.due {
                    d.due = false;
                    d.batch_open = true;
                    d.batch_pending = true;
                }
                self.check_growth(i, name, quiet);
                if !self.violation.is_empty() {
                    return;
                }
                if self.service {
                    self.service_committed(i, name, base, now, &inflight);
                    if !self.violation.is_empty() {
                        return;
                    }
                }
            } else {
                self.fail(
                    i,
                    format!("commit jumped {name} from version {base} to {now}"),
                );
                return;
            }
        }
        if self.relaxed && !self.disk().fired.is_empty() {
            return; // a failed cap flush revoked the storage; the recovery that follows checks it
        }
        if let Err(e) = self.check_live() {
            self.fail(i, format!("after commit: {e}"));
        }
    }

    /// The page-service checks after a commit of main published version `now` over `base` (S8). A
    /// page client's commit must obey the commit-role rule (page-service.md §6): it never rebuilds the
    /// free list, so the free list it persists is a subset of its base's. And an owner may follow a
    /// client's commit with a maintenance commit — the unchanged snapshot at the next versions —
    /// which joins the history with the same contents.
    fn service_committed(&mut self, i: usize, name: &str, base: u64, now: u64, digest: &str) {
        if self
            .db()
            .sim_service_db(name)
            .is_none_or(|db| db.sim_page_client().is_none())
        {
            return;
        }
        if let Some(image) = self.image(name)
            && let (Some(before), Some(after)) = (
                sim_free_list(&image, self.page_size, base),
                sim_free_list(&image, self.page_size, now),
            )
        {
            let was: HashSet<u32> = before.into_iter().collect();
            if let Some(pg) = after.into_iter().find(|pg| !was.contains(pg)) {
                self.fail(
                    i,
                    format!(
                        "commit-role rule: a page client's commit (version {now}) freed page {pg}, which its base's free list does not hold"
                    ),
                );
                return;
            }
        }
        if self.disk().dead() {
            // The owner died later in this step; it may have been writing a maintenance commit,
            // which recovery may select: the same contents at the next version.
            let d = self.sdb(name);
            d.add_history(now + 1, digest.to_string());
            d.max_attempted = d.max_attempted.max(now + 1);
            return;
        }
        let Some(owner) = self.owner_pid_of(name) else {
            return;
        };
        let owner_db = &self.procs[&owner].db;
        let ov = if name == "main" {
            owner_db.version()
        } else {
            owner_db.sim_attached_version(name).unwrap_or(0)
        };
        if ov <= now {
            return;
        }
        let relaxed = self.relaxed;
        let d = self.sdb(name);
        for v in now + 1..=ov {
            d.add_history(v, digest.to_string());
        }
        d.version = ov;
        d.max_attempted = d.max_attempted.max(ov);
        if !relaxed {
            d.floor = ov; // the maintenance commit is an owner commit: batched under synchronous = off
        }
        if name == "main" {
            self.emit(format!(
                "{{\"i\":{i},\"op\":\"maintenance\",\"version\":{ov}}}"
            ));
        } else {
            self.emit(format!(
                "{{\"i\":{i},\"op\":\"maintenance\",\"db\":{},\"version\":{ov}}}",
                go_quote(name)
            ));
        }
    }

    /// Whether the process writing database `name` holds no relaxed commit pending a flush — no
    /// pending set, no adopted generation awaiting stabilization, no failed barrier — so its
    /// published version is the one it treats as durable (validated-cow.md §4). Under the page
    /// service the owner writes the file; with no owner running, nothing is claimed.
    fn engine_flushed(&self, name: &str) -> bool {
        let db = if self.service {
            let Some(owner) = self.owner_pid_of(name) else {
                return false;
            };
            &self.procs[&owner].db
        } else {
            match &self.db {
                Some(db) => db,
                None => return false,
            }
        };
        db.sim_engine_flushed(name)
    }

    /// Whether the process writing database `name` holds a non-empty pending set — a relaxed batch
    /// not yet flushed (validated-cow.md §4). Not run under the page service.
    fn engine_pending(&self, name: &str) -> bool {
        if self.service {
            return false;
        }
        self.db
            .as_ref()
            .is_some_and(|db| db.sim_engine_pending(name))
    }

    /// Check trailing truncation against batched durability (§8.3, validated-cow.md §4). The file
    /// never shrinks below the durable floor's high-water: while a relaxed batch is pending the floor
    /// is the only generation recovery is sure to find, so a shrink before the flush must not cut its
    /// pages. And once the engine holds nothing pending again, a shrink that a relaxed commit deferred
    /// has happened: the file is at most one growth step past the published high-water.
    fn check_truncated(&mut self, i: usize, name: &str) -> bool {
        let (floor, version, shrink_due) = {
            let d = &self.dbs[name];
            (d.floor, d.version, d.shrink_due)
        };
        let (image, stopped) = {
            let file = self.dbs[name].file.clone();
            let disk = self.disk();
            (
                disk.image(&file),
                disk.dead() || !disk.fired.is_empty() || disk.armed(),
            )
        };
        let Some(image) = image else {
            return true;
        };
        let length = image.len() as u64;
        let ps = self.page_size as u64;
        if let Some((pc, _)) = sim_meta_of(&image, self.page_size, floor)
            && pc as u64 * ps > length
        {
            self.fail(
                i,
                format!(
                    "trailing truncation: {name}'s file is {length} bytes, shorter than its durable version {floor}'s {pc} pages"
                ),
            );
            return false;
        }
        if !shrink_due {
            return true;
        }
        if stopped {
            self.sdb(name).shrink_due = false; // a crash or fault may have cut the flush short
            return true;
        }
        if !self.engine_flushed(name) {
            return true;
        }
        self.sdb(name).shrink_due = false;
        let Some((pc, _)) = sim_meta_of(&image, self.page_size, version) else {
            return true;
        };
        let limit = (pc as u64 + crate::pager::growth_step(pc, self.page_size) as u64) * ps;
        if length > limit {
            self.fail(
                i,
                format!(
                    "trailing truncation: {name} flushed a batch that lowered its high-water to {pc} pages but its file is {length} bytes (at most {limit})"
                ),
            );
            return false;
        }
        true
    }

    // --- bounded growth (simulation-testing.md §8.3) ---

    /// Database `name`'s page high-water and free-list length in the running process — the allocator
    /// state the next commit draws from — and where the free list's trailing run starts.
    fn allocator(&self, name: &str) -> (u32, u32, u32) {
        self.db().sim_allocator(name).unwrap_or((0, 0, 0))
    }

    /// Start a new bounded-growth lifetime for database `name` (an open, a recovery, a compaction, an
    /// attach). The engine seeds its reclamation trigger with the page count minus the free list
    /// (format.md *Reclamation*), so a file whose dead pages are not all listed is reclaimed only
    /// after it doubles.
    fn observe_growth(&mut self, name: &str) {
        let (pc, free, trail) = self.allocator(name);
        let d = self.sdb(name);
        d.high = pc;
        d.free = free;
        d.trail = trail;
        d.lac_bound = pc.wrapping_sub(free);
        d.last = Growth::default();
    }

    /// Check the reader-aware bounded-growth invariant after a commit published a new version of
    /// database `name` (simulation-testing.md §8.3). With no reader pinned, no other process, and no
    /// fault, the engine reclaims in the commit once the pages off its free list pass compact_growth
    /// × the live count at its last reclamation (memory.md §8.4); readers legitimately hold
    /// reclamation back, so a commit with one open is not checked. A commit only adds pages off the
    /// list (each page it allocates leaves the list or grows the file), so the count it began with is
    /// a lower bound. Two checks follow:
    ///   - a quiet commit that began with more pages off the list than max(compact_min_pages,
    ///     compact_growth × an upper bound on that live count) must have reclaimed: every page below
    ///     the high-water is meta, live, free, or written by the commit itself (its manifest and
    ///     free-list pages);
    ///   - the next quiet commit reuses that free list before it grows the file.
    fn check_growth(&mut self, i: usize, name: &str, quiet: bool) {
        if self.service {
            return;
        }
        let version = self.dbs[name].version;
        let Some((pc, live)) = self
            .image(name)
            .and_then(|image| sim_meta_of(&image, self.page_size, version))
        else {
            return;
        };
        let (_, free, trail) = self.allocator(name);
        let (written, top, length) = {
            let file = self.dbs[name].file.clone();
            let disk = self.disk();
            disk.file(&file).map_or((0, 0, 0), |id| {
                let pages = disk.written_pages(id).iter().filter(|pg| **pg >= 2);
                let top = pages.clone().max().map_or(0, |pg| *pg as u32 + 1);
                (pages.count() as u32, top, disk.file_len(id))
            })
        };
        // Trailing truncation (§8.3): a quiet commit passes the reuse gate, so its tree pages take the
        // lowest free pages, whatever of the old trailing run they leave is truncated, and every later
        // page comes from the high-water at the run's start.
        // A commit inside a relaxed batch never lowers the high-water (validated-cow.md §4), so it
        // only grows it to what it wrote.
        let (prev_high, prev_trail) = (self.dbs[name].high, self.dbs[name].trail);
        let in_batch = self.dbs[name].batch_pending;
        if quiet && in_batch && pc != prev_high.max(top) {
            self.fail(
                i,
                format!(
                    "trailing truncation: {name} has {pc} pages after a commit inside a relaxed batch that wrote up to page {top}, from {prev_high} pages"
                ),
            );
            return;
        }
        if quiet && !in_batch && pc != prev_trail.max(top) {
            self.fail(
                i,
                format!(
                    "trailing truncation: {name} has {pc} pages after a quiet commit that wrote up to page {top}, from {prev_high} pages whose free list's trailing run began at {prev_trail}"
                ),
            );
            return;
        }
        if quiet && pc < prev_high && self.relaxed {
            // The shrink waits for the batch's flush (validated-cow.md §4): checked when the engine
            // next holds nothing pending (check_truncated).
            self.sdb(name).shrink_due = true;
        } else if quiet && pc < prev_high {
            let limit = (pc as u64 + crate::pager::growth_step(pc, self.page_size) as u64)
                * self.page_size as u64;
            if length > limit {
                self.fail(
                    i,
                    format!(
                        "trailing truncation: {name} lowered its high-water to {pc} pages but its file is {length} bytes (at most {limit})"
                    ),
                );
                return;
            }
        }
        let (before, unlisted, lac_bound) = {
            let d = &self.dbs[name];
            (d.last, d.high.wrapping_sub(d.free), d.lac_bound)
        };
        if self.dbs[name].batch_open {
            // A commit inside a relaxed batch neither reuses nor frees the batch's pages
            // (validated-cow.md §4); only the bounds carry forward.
            let d = self.sdb(name);
            d.high = pc;
            d.free = free;
            d.trail = trail;
            d.lac_bound = d.lac_bound.max(live.wrapping_add(written));
            d.last = Growth::default();
            return;
        }
        if quiet
            && before.reclaimed
            && pc > before.high
            && pc - before.high > written - written.min(before.free)
        {
            self.fail(
                i,
                format!(
                    "bounded growth: {name} grew from {} to {pc} pages writing {written}, with {} free pages to reuse",
                    before.high, before.free
                ),
            );
            return;
        }
        let mut reclaimed = false;
        if quiet
            && unlisted as u64 > (COMPACT_MIN_PAGES as u64).max(COMPACT_GROWTH * lac_bound as u64)
        {
            reclaimed = true;
            let leaked = pc.wrapping_sub(2).wrapping_sub(live).wrapping_sub(free);
            if (pc as u64) < 2 + live as u64 + free as u64 || leaked > written {
                self.fail(
                    i,
                    format!(
                        "bounded growth: {name} has {pc} pages, {live} live and {free} free, after a commit that wrote {written} must have reclaimed every dead page"
                    ),
                );
                return;
            }
        }
        let d = self.sdb(name);
        d.high = pc;
        d.free = free;
        d.trail = trail;
        d.lac_bound = d.lac_bound.max(live.wrapping_add(written));
        d.last = Growth {
            reclaimed,
            high: pc,
            free,
        };
    }

    fn step_end(&mut self, i: usize, st: &Step) {
        let sid = go_quote(&st.sid);
        let op = go_quote(&st.kind);
        let Some(mut ss) = self.sessions.remove(&st.sid) else {
            self.emit(format!(
                "{{\"i\":{i},\"op\":{op},\"sid\":{sid},\"skip\":true}}"
            ));
            return;
        };
        self.sessions_changed();
        if st.kind == "rollback" {
            if let Err(e) = ss.s.rollback() {
                self.emit(format!(
                    "{{\"i\":{i},\"op\":\"rollback\",\"sid\":{sid},\"error\":{}}}",
                    go_quote(&engine_code(&e))
                ));
                return;
            }
        } else {
            // Snapshot isolation: a reader still sees exactly the version of every database it
            // pinned, however many commits, reclamations, and page reuses happened since.
            let mut lost = false;
            if !ss.write {
                for name in self.order() {
                    let Some(&pin) = ss.pins.get(&name) else {
                        continue;
                    };
                    let d = self.digest_of(&mut ss.s, &name);
                    if d.is_none()
                        && self.service
                        && self
                            .digest_err
                            .as_ref()
                            .is_some_and(|e| e.code() == "08006")
                    {
                        // Under the page service a read transaction open across a change of its
                        // process's role fails 08006 (spec/pageservice/README.md §6.5): it never sees
                        // other contents.
                        lost = true;
                        break;
                    }
                    let ok = d.is_some_and(|d| self.dbs[&name].in_history(pin, &d));
                    if !ok {
                        self.fail(
                            i,
                            format!(
                                "isolation: reader {} no longer sees version {pin} of {name}",
                                st.sid
                            ),
                        );
                        break;
                    }
                }
            }
            ss.s.close();
            if lost {
                self.emit(format!(
                    "{{\"i\":{i},\"op\":{op},\"sid\":{sid},\"lost\":true}}"
                ));
                return;
            }
        }
        self.emit(format!("{{\"i\":{i},\"op\":{op},\"sid\":{sid}}}"));
    }

    /// Host compaction (api.md §2.6) of database `name`: the committed snapshot rewritten as a fresh
    /// image at the next version, through the simulated filesystem's temp file, rename, and
    /// directory barrier. Its contents are unchanged, so a crash may recover either version with the
    /// same digest.
    /// `rekey <n>|plain [<db>]` (S12–S13): compaction under a new data key for simulation key
    /// `target`, which encrypts a plaintext database, or with -1 a decryption.
    fn step_rekey(&mut self, i: usize, name: &str, target: i32) {
        if !self.encrypted {
            self.emit(format!("{{\"i\":{i},\"op\":\"rekey\",\"skip\":true}}"));
            return;
        }
        self.step_compact(i, name, Some(target));
    }

    fn step_compact(&mut self, i: usize, name: &str, rekey: Option<i32>) {
        // A rekey (S12) is compaction under a new data key: the same version and contents rules.
        let op = if rekey.is_some() { "rekey" } else { "compact" };
        if !self.dbs.contains_key(name) || self.db_version(name) == 0 {
            self.emit(format!(
                "{{\"i\":{i},\"op\":\"{op}\",\"db\":{},\"skip\":true}}",
                go_quote(name)
            ));
            return;
        }
        let (base, last_digest) = {
            let d = self.sdb(name);
            d.add_history(d.version + 1, d.last_digest.clone());
            d.max_attempted = d.max_attempted.max(d.version + 1);
            (d.version, d.last_digest.clone())
        };
        let result = match rekey {
            Some(target) => {
                let file = self.dbs[name].file.clone();
                let entry_pending = !self.disk().entry_durable(&file);
                let d = self.sdb(name);
                d.key_change = Some(KeyChange {
                    old: d.key,
                    next: target,
                    entry_pending,
                });
                let result = self.db().rekey(
                    name,
                    sim_credential(target).cloned(),
                    crate::crypto::Argon2Params::default(),
                );
                if result.is_ok() {
                    self.sdb(name).key = target;
                }
                result
            }
            None => self.db().compact(name),
        };
        let now = self.db_version(name);
        let db_field = if name == "main" {
            String::new()
        } else {
            format!(",\"db\":{}", go_quote(name))
        };
        if let Err(e) = result {
            let code = engine_code(&e);
            self.emit(format!(
                "{{\"i\":{i},\"op\":\"{op}\"{db_field},\"error\":{}}}",
                go_quote(&code)
            ));
            if code == "XX001" {
                self.fail(i, format!("corruption: {op} reported XX001: {e}"));
            } else if now > base || (now != base && !self.service) {
                // (A page client's view may lag the owner's until its next begin.)
                self.fail(
                    i,
                    format!("a failed {op} published version {now} of {name} (was {base})"),
                );
            }
            return;
        }
        self.emit(format!(
            "{{\"i\":{i},\"op\":\"{op}\"{db_field},\"version\":{now}}}"
        ));
        if now != base + 1 {
            self.fail(i, format!("{op} moved {name} from version {base} to {now}"));
            return;
        }
        let d = self.committed_digest(name);
        if d.as_deref() != Some(last_digest.as_str()) {
            self.fail(i, format!("{op} changed the contents of {name}"));
            return;
        }
        if let Err(e) = self.check_live() {
            self.fail(i, format!("after {op}: {e}"));
            return;
        }
        let d = self.sdb(name);
        d.version = now;
        d.floor = now; // the rename and the directory barrier completed
        self.observe_growth(name);
    }

    /// `change_key <n> [<db>]` (S12–S13, encrypted.md §5): the credential of main or a file
    /// attachment changes to simulation key `n`. Only the key block is written, so no version or
    /// content moves. A plaintext database refuses it (28P03).
    fn step_change_key(&mut self, i: usize, name: &str, n: i32) {
        if !self.encrypted || !self.dbs.contains_key(name) || self.db_version(name) == 0 {
            self.emit(format!(
                "{{\"i\":{i},\"op\":\"change_key\",\"db\":{},\"skip\":true}}",
                go_quote(name)
            ));
            return;
        }
        let db_field = if name == "main" {
            String::new()
        } else {
            format!(",\"db\":{}", go_quote(name))
        };
        let base = self.db_version(name);
        let file = self.dbs[name].file.clone();
        let entry_pending = !self.disk().entry_durable(&file);
        let d = self.sdb(name);
        d.key_change = Some(KeyChange {
            old: d.key,
            next: n,
            entry_pending,
        });
        let result = self.db().change_credential(
            name,
            SIM_KEYS[n as usize].clone(),
            crate::crypto::Argon2Params::default(),
        );
        match result {
            Ok(()) => {
                self.sdb(name).key = n;
                self.emit(format!(
                    "{{\"i\":{i},\"op\":\"change_key\"{db_field},\"key\":{n}}}"
                ));
            }
            Err(e) => {
                let code = engine_code(&e);
                self.emit(format!(
                    "{{\"i\":{i},\"op\":\"change_key\"{db_field},\"error\":{}}}",
                    go_quote(&code)
                ));
                if code == "XX001" {
                    self.fail(i, format!("corruption: change_key reported XX001: {e}"));
                }
            }
        }
        if self.db_version(name) != base {
            self.fail(
                i,
                format!("a credential change published a version of {name}"),
            );
        }
    }

    /// `backup page_identical|compacted [p<N>]` (spec/design/page-service.md §9): the process backs
    /// main up into a new file through the simulated filesystem, while every other session keeps its
    /// pins and its writer gate. A backup that fails leaves no destination. One that succeeds is
    /// checked at once, as a new process would open it: its version is the pinned snapshot's
    /// (page-identical) or the one after it (compacted), the snapshot is the newest committed
    /// generation, its contents are that generation's, and the integrity checker accepts the image.
    /// Its image hash makes the cores' backups byte-identical (§8.4).
    fn step_backup(&mut self, i: usize, st: &Step) {
        self.backups += 1;
        let dest = format!("{}.backup{}", self.main_db().file, self.backups);
        let form = go_quote(&st.mode);
        if let Err(e) = self
            .db()
            .backup_for_testing(&dest, st.mode == "page_identical")
        {
            let code = engine_code(&e);
            self.emit(format!(
                "{{\"i\":{i},\"op\":\"backup\",\"form\":{form},\"error\":{}}}",
                go_quote(&code)
            ));
            if code == "XX001" {
                self.fail(i, format!("corruption: backup reported XX001: {e}"));
            } else if self.disk().file(&dest).is_some() {
                self.fail(i, "a failed backup left its destination".to_string());
            }
            return;
        }
        let Some(image) = self.disk().image(&dest) else {
            self.fail(i, "a successful backup left no destination".to_string());
            return;
        };
        if let Some(prefix) = &self.image_prefix {
            let _ = std::fs::write(format!("{}.step{i}.backup.img", prefix.display()), &image);
        }
        // The copy opens with the database's credential at the time of the backup
        // (encrypted.md §13).
        let opened = Pager::from_store(Box::new(crate::blockstore::MemoryBlockStore::new(
            image.clone(),
        )))
        .and_then(|pager| {
            let ps = pager.page_size();
            Engine::open_paged(
                pager,
                cache_leaves(DEFAULT_CACHE_BYTES, ps),
                &self.proc_env(),
                self.credential("main"),
            )
        });
        let engine = match opened {
            Ok(engine) => engine,
            Err(e) => {
                let opens = (-1..4)
                    .filter(|&k| self.sim_unlocks(Some(&image), k))
                    .last()
                    .unwrap_or(-2);
                let key = self.main_db().key;
                self.fail(
                    i,
                    format!("the backup does not open with key {key}: {e} (key {opens} opens it)"),
                );
                return;
            }
        };
        let v = engine.committed.txid;
        let snapshot = if st.mode == "compacted" { v - 1 } else { v };
        let copy = Database::from_engine(engine);
        let mut rs = copy.read_session();
        let dg = self.digest_of(&mut rs, "main");
        rs.close();
        let _ = copy.close();
        let main_version = self.main_db().version;
        // A dead owner's batch may be lost back to the floor (§8.2): a backup that promotes its
        // process, or reaches a new owner, may then copy any version from the floor up.
        let owner_lost = self.main_db().owner_lost;
        let floor = self.main_db().floor;
        let dg = match dg {
            None => {
                let why = self
                    .digest_err
                    .as_ref()
                    .map_or("<nil>".to_string(), |e| e.to_string());
                self.fail(i, format!("the backup cannot be read: {why}"));
                return;
            }
            Some(_) if snapshot < main_version && (!owner_lost || snapshot < floor) => {
                self.fail(
                    i,
                    format!(
                        "the backup copied version {snapshot}, older than the committed {main_version}"
                    ),
                );
                return;
            }
            Some(dg) if !self.main_db().in_history(snapshot, &dg) => {
                self.fail(
                    i,
                    format!("the backup holds contents (digest {dg}) version {snapshot} never had"),
                );
                return;
            }
            Some(dg) => dg,
        };
        if owner_lost {
            // The backup's pin is the first look at main since its owner died: what it copied is
            // now the committed generation, as observe records for a session.
            let m = self.main_db_mut();
            m.version = snapshot;
            m.last_digest = dg.clone();
            m.owner_lost = false;
        }
        let (live, pages, free) = match check::integrity(&image, v, self.credential("main")) {
            Ok(r) => r,
            Err(e) => {
                self.fail(i, format!("backup integrity: {e}"));
                return;
            }
        };
        self.backups_ok.push(SimBackup {
            n: self.backups,
            file: dest.clone(),
            version: v,
            digest: dg.clone(),
            key: self.main_db().key,
        });
        let hash = image_hash(&image, pages, self.page_size);
        self.emit(format!(
            "{{\"i\":{i},\"op\":\"backup\",\"form\":{form},\"version\":{v},\"digest\":{},\"live\":{live},\"pages\":{pages},\"free\":{free},\"image\":\"{hash:016x}\"}}",
            go_quote(&dg)
        ));
    }

    /// Attach file database `name` to the running process (S4), first creating its file through the
    /// simulated filesystem if it does not exist — create's temp file, sync, rename, and directory
    /// barrier, any of which a fault may interrupt. Already attached, it only reports.
    fn step_attach(&mut self, i: usize, name: &str) {
        // Attaching takes the writer gate. The generator never attaches while a writer is open; a
        // trace that does (a shrinking artifact) would wait forever on this one thread, so it is
        // invalid.
        let mut writers: Vec<&String> = self
            .sessions
            .iter()
            .filter(|(_, ss)| ss.write)
            .map(|(sid, _)| sid)
            .collect();
        writers.sort();
        if let Some(sid) = writers.first() {
            let msg = format!("attach {name} while {sid} holds the writer gate");
            self.fail(i, msg);
            return;
        }
        if self.dbs.contains_key(name)
            && self.db_version(name) != 0
            && (!self.service || self.attached_in_all(name))
        {
            let v = self.dbs[name].version;
            self.emit(format!(
                "{{\"i\":{i},\"op\":\"attach\",\"db\":{},\"version\":{v}}}",
                go_quote(name)
            ));
            return;
        }
        if !self.dbs.contains_key(name) {
            self.dbs
                .insert(name.to_string(), SimDb::new(&format!("{name}.jed")));
        }
        let file = self.dbs[name].file.clone();
        if self.disk().file(&file).is_none() {
            // A fresh file is version 1, empty. Until create returns it may vanish in a crash
            // (floor 0).
            let empty = empty_digest(name);
            {
                let d = self.sdb(name);
                d.history = HashMap::new();
                d.add_history(1, empty.clone());
                d.version = 1;
                d.last_digest = empty;
                d.floor = 0;
                d.max_attempted = 1;
            }
            let key = self.create_key();
            self.sdb(name).key = key;
            let cur = self.cur;
            let env = self.new_env(cur);
            let created = Engine::create_via(
                &SimHost(self.fs.clone()),
                Path::new(&file),
                DatabaseOptions {
                    page_size: self.page_size,
                    no_sync: false,
                },
                sim_credential(key).map(|credential| crate::file::Encryption {
                    credential,
                    kdf: crate::crypto::Argon2Params::default(),
                    environment: &env,
                }),
            );
            match created {
                Ok(e) => {
                    let _ = e.close();
                }
                Err(e) => {
                    self.attach_failed(i, name, e);
                    return;
                }
            }
            self.sdb(name).floor = 1; // create returned: the file and its directory entry are durable
        }
        if self.service {
            if !self.attach_everywhere(i, name) {
                return;
            }
        } else if let Err(e) = self.attach(name) {
            self.attach_failed(i, name, e);
            return;
        }
        let v = self.db_version(name);
        let d = self.committed_digest(name);
        if !self.check_recovered(i, name, v, d, "attached") {
            return;
        }
        self.observe_growth(name);
        self.emit(format!(
            "{{\"i\":{i},\"op\":\"attach\",\"db\":{},\"version\":{v}}}",
            go_quote(name)
        ));
    }

    fn attach_failed(&mut self, i: usize, name: &str, e: EngineError) {
        let code = engine_code(&e);
        if code == "XX001" {
            self.fail(i, format!("attach {name}: {e}"));
            return;
        }
        self.emit(format!(
            "{{\"i\":{i},\"op\":\"attach\",\"db\":{},\"error\":{}}}",
            go_quote(name),
            go_quote(&code)
        ));
    }

    fn step_check(&mut self, i: usize) {
        let mut entries: Vec<String> = Vec::new();
        let mut main_line = String::new();
        for name in self.order() {
            if self.service && name != "main" && self.db_version(&name) == 0 {
                // This process is not attached to it: a faulted attach killed the process attaching
                // it before this one did; the next attach step repairs that.
                continue;
            }
            let (v, d) = self.committed_view(&name);
            let d = if self.service {
                // Another process may have died leaving a newer complete generation this one now
                // adopts.
                if !self.observe_db(i, &name, "check", v, d) {
                    return;
                }
                self.dbs[&name].last_digest.clone()
            } else {
                let db = &self.dbs[&name];
                match d.filter(|d| v == db.version && *d == db.last_digest) {
                    Some(d) => d,
                    None => {
                        self.fail(
                            i,
                            format!(
                                "a read session does not see the last committed version of {name}"
                            ),
                        );
                        return;
                    }
                }
            };
            let version = self.dbs[&name].version;
            let image = self.image(&name).unwrap_or_default();
            let (live, pages, free) =
                match check::integrity(&image, version, self.credential(&name)) {
                    Ok(r) => r,
                    Err(e) => {
                        self.fail(i, format!("integrity of {name}: {e}"));
                        return;
                    }
                };
            let hash = image_hash(&image, pages, self.page_size);
            let body = format!(
                "\"version\":{version},\"digest\":{},\"live\":{live},\"pages\":{pages},\"free\":{free},\"image\":\"{hash:016x}\"",
                go_quote(&d)
            );
            if name == "main" {
                main_line = body;
            } else {
                entries.push(format!("{}:{{{body}}}", go_quote(&name)));
            }
        }
        if let Err(e) = self.check_live() {
            self.fail(i, format!("live integrity: {e}"));
            return;
        }
        self.emit(format!(
            "{{\"i\":{i},\"op\":\"check\",{main_line}{}}}",
            dbs_json(&entries)
        ));
    }

    /// Raise each database's floor to its published version after every process closed cleanly under
    /// synchronous = off, when the close left every byte of the file and its directory entry durable:
    /// a clean close flushes the batch (validated-cow.md §4). A generation a recovered process adopted
    /// and never had to stabilize (it wrote nothing) may still be pending, and keeps its floor (§8.2).
    /// So does a database whose owner died: what it published may be gone until a process observes
    /// the database again.
    fn close_flushed(&mut self) {
        if !self.relaxed {
            return;
        }
        for name in self.order() {
            let (file, version, floor) = {
                let d = &self.dbs[&name];
                if d.owner_lost {
                    continue;
                }
                (d.file.clone(), d.version, d.floor)
            };
            let durable = {
                let disk = self.disk();
                disk.file(&file)
                    .is_some_and(|id| !disk.has_pending(id) && disk.entry_durable(&file))
            };
            if durable && version > floor {
                self.dbs.get_mut(&name).unwrap().floor = version;
            }
        }
    }

    /// End every session cleanly, close the Database, and reopen it: the result must be exactly the
    /// last committed version of every database.
    fn step_reopen(&mut self, i: usize) -> bool {
        for pid in self.live_pids() {
            if let Err(e) = self.close_proc(pid) {
                self.fail(i, format!("close: {e}"));
                return false;
            }
        }
        // Close flushed every batch, so a shrink a relaxed commit deferred has happened, and the floor
        // the file is held to is the version it flushed (validated-cow.md §4), not the one before it.
        self.close_flushed();
        for name in self.order() {
            if !self.check_truncated(i, &name) {
                return false;
            }
        }
        self.disk().process_death();
        if let Err(e) = self.open() {
            self.fail(i, format!("reopen failed: {e}"));
            return false;
        }
        let mut entries: Vec<String> = Vec::new();
        let mut main_v = 0;
        let mut main_d = String::new();
        for name in self.order() {
            let v = self.db_version(&name);
            if v == 0 && name != "main" && self.service && self.dbs[&name].floor == 0 {
                let file = self.dbs[&name].file.clone();
                if self.disk().file(&file).is_none() {
                    // A faulted attach killed its owner before create returned (S8 kills only the
                    // owner, so no recovery ran to forget it): the file may legitimately be gone.
                    self.dbs.remove(&name);
                    continue;
                }
            }
            if v == 0 {
                self.fail(i, format!("a clean reopen lost attachment {name}"));
                return false;
            }
            let d = self.committed_digest(&name);
            let shown = d.clone().unwrap_or_default();
            if self.service {
                // A process killed mid-commit may have left a complete generation no survivor began
                // on yet.
                if !self.observe_db(i, &name, "reopened p0", v, d) {
                    return false;
                }
            } else {
                let db = &self.dbs[&name];
                if v != db.version || d.as_deref() != Some(db.last_digest.as_str()) {
                    let msg = format!(
                        "a clean reopen returned version {v} of {name} (digest {shown}), want version {} (digest {})",
                        db.version, db.last_digest
                    );
                    self.fail(i, msg);
                    return false;
                }
            }
            self.observe_growth(&name);
            if name == "main" {
                main_v = v;
                main_d = shown;
            } else {
                entries.push(format!(
                    "{}:{{\"version\":{v},\"digest\":{}}}",
                    go_quote(&name),
                    go_quote(&shown)
                ));
            }
        }
        self.emit(format!(
            "{{\"i\":{i},\"op\":\"reopen\",\"version\":{main_v},\"digest\":{}{}}}",
            go_quote(&main_d),
            dbs_json(&entries)
        ));
        true
    }

    /// Check database `name`'s version and contents after a recovery or an attach against its
    /// history and durability floor (§8.1–8.2).
    fn check_recovered(
        &mut self,
        i: usize,
        name: &str,
        v: u64,
        d: Option<String>,
        what: &str,
    ) -> bool {
        let db = &self.dbs[name];
        let msg = match &d {
            None => Some(format!(
                "{what}: version {v} of {name} is unreadable: {}",
                self.digest_err
                    .as_ref()
                    .map_or("<nil>".to_string(), |e| e.to_string())
            )),
            Some(_) if v < db.floor => Some(format!(
                "durability: {what} version {v} of {name}, but version {} was durable",
                db.floor
            )),
            Some(_) if v > db.max_attempted => Some(format!(
                "{what}: version {v} of {name} was never attempted (latest attempted {})",
                db.max_attempted
            )),
            Some(d) if !db.in_history(v, d) => Some(format!(
                "{what}: version {v} of {name} has contents (digest {d}) no transaction produced"
            )),
            Some(_) => None,
        };
        if let Some(msg) = msg {
            self.fail(i, msg);
            return false;
        }
        let db = self.sdb(name);
        db.version = v;
        db.last_digest = d.expect("checked above");
        true
    }

    /// Abandon the crashed process — its sessions and Database — and open the disk as a new process
    /// would, then check every database's recovered generation against its history and durability
    /// floor (§8.1–8.2) and its image against the integrity checker (§8.3).
    fn recover(&mut self, i: usize, fired: &str) -> bool {
        for pid in self.live_pids() {
            self.drop_proc(pid);
        }
        self.disk().process_death();
        let mut images: HashMap<String, Vec<u8>> = HashMap::new();
        for name in self.order() {
            let image = self.image(&name);
            let Some(image) = image.or_else(|| (name == "main").then(Vec::new)) else {
                // A crash during the attachment's create: allowed only while create had not
                // returned.
                let floor = self.dbs[&name].floor;
                if floor > 0 {
                    self.fail(
                        i,
                        format!(
                            "durability: attachment {name}'s file is gone, but version {floor} was durable"
                        ),
                    );
                    return false;
                }
                self.dbs.remove(&name);
                continue;
            };
            if let Some(prefix) = &self.image_prefix {
                let suffix = if name == "main" {
                    String::new()
                } else {
                    format!(".{name}")
                };
                let _ = std::fs::write(format!("{}.step{i}{suffix}.img", prefix.display()), &image);
            }
            images.insert(name, image);
        }
        for name in self.order() {
            let image = images.get(&name).cloned();
            if !self.settle_key(i, &name, image.as_deref()) {
                self.crash_image = images.remove(&name);
                return false;
            }
        }
        if let Err(e) = self.open() {
            self.crash_image = images.remove("main");
            self.fail(i, format!("recovery: open failed: {e}"));
            return false;
        }
        let mut entries: Vec<String> = Vec::new();
        let mut main_line = String::new();
        for name in self.order() {
            let v = self.db_version(&name);
            let d = self.committed_digest(&name);
            if !self.check_recovered(i, &name, v, d.clone(), "recovered") {
                self.crash_image = images.remove(&name);
                return false;
            }
            let d = d.expect("checked above");
            let image = &images[&name];
            let (live, pages, free) = match check::integrity(image, v, self.credential(&name)) {
                Ok(r) => r,
                Err(e) => {
                    self.crash_image = images.remove(&name);
                    self.fail(i, format!("recovery integrity of {name}: {e}"));
                    return false;
                }
            };
            let hash = image_hash(image, pages, self.page_size);
            self.observe_growth(&name);
            let body = format!(
                "\"recovered\":{v},\"digest\":{},\"live\":{live},\"pages\":{pages},\"free\":{free},\"image\":\"{hash:016x}\"",
                go_quote(&d)
            );
            if name == "main" {
                main_line = body;
            } else {
                entries.push(format!("{}:{{{body}}}", go_quote(&name)));
            }
        }
        self.emit(format!(
            "{{\"i\":{i},\"op\":\"crash\",\"fired\":{},{main_line}{}}}",
            go_quote(fired),
            dbs_json(&entries)
        ));
        true
    }

    /// `corrupt flips=N [reseal=1]` (simulation-testing.md §6.3): every process ends cleanly; bits
    /// flip in durable body pages of the main database; a new process opens it and reads
    /// everything; then the bits are repaired and the database must reopen exactly as it was.
    /// Without reseal a flip breaks its page's CRC, so every outcome must be XX001 or the right rows
    /// — never wrong rows. With reseal the CRC is recomputed, so only the engine's structural checks
    /// stand in the way: any engine error, or any rows, is allowed, but never a panic.
    fn step_corrupt(&mut self, i: usize, st: &Step) -> bool {
        let reseal = st.params.get("reseal").map(String::as_str) == Some("1");
        for pid in self.live_pids() {
            if let Err(e) = self.close_proc(pid) {
                self.fail(i, format!("close: {e}"));
                return false;
            }
        }
        self.disk().process_death();
        let (version, page_size) = (self.main_db().version, self.page_size);
        let Some(file) = self.disk().file(MAIN_FILE) else {
            self.fail(i, "corrupt: the database file is gone".to_string());
            return false;
        };
        let pc = {
            let image = self.image("main").unwrap_or_default();
            sim_meta_of(&image, page_size, version).map(|(pc, _)| pc)
        };
        let Some(pc) = pc else {
            self.fail(i, format!("corrupt: no meta holds version {version}"));
            return false;
        };
        let flips = self
            .disk()
            .corrupt(file, i as u64, st.int_param("flips"), pc, reseal);
        let mut opened = "ok".to_string();
        let mut read = "-".to_string();
        match self.open_proc(0) {
            Err(e) => match self.corrupt_outcome(i, reseal, &e) {
                Some(code) => opened = code,
                None => return false,
            },
            Ok(()) => {
                read = "ok".to_string();
                let v = self.db().version();
                match self.committed_digest("main") {
                    None => {
                        let e = self
                            .digest_err
                            .take()
                            .expect("a failed digest records its error");
                        match self.corrupt_outcome(i, reseal, &e) {
                            Some(code) => read = code,
                            None => return false,
                        }
                    }
                    Some(_) if reseal => {}
                    Some(d) => {
                        let m = self.main_db();
                        if !m.in_history(v, &d)
                            || v > m.version
                            || (v < m.version && v + 1 != m.version)
                        {
                            // A flip in the newest generation's dirty pages fails its validation,
                            // and recovery falls back to the previous generation
                            // (validated-cow.md §1), which is intact.
                            self.fail(
                                i,
                                format!(
                                    "corrupt: version {v} read back with contents (digest {d}) no transaction produced"
                                ),
                            );
                            return false;
                        }
                    }
                }
                self.drop_proc(0);
            }
        }
        self.disk().repair(file, &flips);
        if let Err(e) = self.open() {
            self.fail(i, format!("corrupt: reopen after repair failed: {e}"));
            return false;
        }
        let v = self.db().version();
        if v != version {
            self.fail(
                i,
                format!("corrupt: after repair version {v}, want {version}"),
            );
            return false;
        }
        let d = self.committed_digest("main");
        if d.as_deref() != Some(self.main_db().last_digest.as_str()) {
            self.fail(i, "corrupt: after repair the contents differ".to_string());
            return false;
        }
        self.emit(format!(
            "{{\"i\":{i},\"op\":\"corrupt\",\"flipped\":{},\"open\":{},\"read\":{}}}",
            flips.len(),
            go_quote(&opened),
            go_quote(&read)
        ));
        true
    }

    /// After a replay or a restore: main reopens exactly as the oracle state says, and every
    /// database's growth bounds start over.
    fn reopen_as_was(&mut self, i: usize, what: &str) -> bool {
        if let Err(e) = self.open() {
            self.fail(i, format!("{what}: reopen failed: {e}"));
            return false;
        }
        let version = self.main_db().version;
        let v = self.db().version();
        if v != version {
            self.fail(
                i,
                format!("{what}: after the repair version {v}, want {version}"),
            );
            return false;
        }
        let d = self.committed_digest("main");
        if d.as_deref() != Some(self.main_db().last_digest.as_str()) {
            self.fail(i, format!("{what}: after the repair the contents differ"));
            return false;
        }
        for name in self.order() {
            self.observe_growth(&name);
        }
        true
    }

    /// `replay <kind>` (simulation-testing.md §8.3 *Replays*, S13): every process ends cleanly; a
    /// page of main that a bound pointer of `kind` names gets back an older durable version of itself
    /// (§6.1's archive); a new process opens main and reads every row, and the image checker reads
    /// every other reachable page. A page the selected generation's manifest depends on may make
    /// recovery fall back to the generation in the other meta slot; any other replay must surface as
    /// XX001. Then the page is put back and main must reopen exactly as it was.
    fn step_replay(&mut self, i: usize, kind: &str) -> bool {
        for pid in self.live_pids() {
            if let Err(e) = self.close_proc(pid) {
                self.fail(i, format!("close: {e}"));
                return false;
            }
        }
        self.close_flushed();
        self.disk().process_death();
        let file = self.disk().file(MAIN_FILE);
        let skip = format!(
            "{{\"i\":{i},\"op\":\"replay\",\"kind\":{},\"skip\":true}}",
            go_quote(kind)
        );
        let Some(file) = file.filter(|_| self.main_db().key >= 0) else {
            // A plaintext file binds no pointer.
            self.emit(skip);
            return self.reopen_as_was(i, "replay");
        };
        let image = self.image("main").unwrap_or_default();
        let (version, last_digest) = (self.main_db().version, self.main_db().last_digest.clone());
        let (kinds, deps) = match crate::format::sim_pointer_kinds(&image, self.credential("main"))
        {
            Ok(r) => r,
            Err(e) => {
                self.fail(
                    i,
                    format!("replay: classifying the pages of version {version}: {e}"),
                );
                return false;
            }
        };
        let cands: Vec<(u32, Vec<Vec<u8>>)> = {
            let disk = self.disk();
            kinds
                .get(kind)
                .map(|pages| {
                    pages
                        .iter()
                        .map(|&pg| (pg, disk.replay_versions(file, pg as u64)))
                        .filter(|(_, vs)| !vs.is_empty())
                        .collect()
                })
                .unwrap_or_default()
        };
        if cands.is_empty() {
            self.emit(skip);
            return self.reopen_as_was(i, "replay");
        }
        let (page, versions) = &cands
            [(decide(self.seed, LANE_REPLAY_PAGE, i as u64, 0, 0) % cands.len() as u64) as usize];
        let older = &versions[(decide(self.seed, LANE_REPLAY_VERSION, i as u64, 0, 0)
            % versions.len() as u64) as usize];
        let page = *page;
        // The generation in the other meta slot, the one a fallback recovers.
        let ps = self.page_size as usize;
        let mut other = 0u64;
        for slot in 0..2 {
            if let Some(block) = image.get(slot * ps..(slot + 1) * ps)
                && let Some((txid, _)) = crate::format::meta_txid_and_page_count(block)
                && txid < version
                && txid > other
            {
                other = txid;
            }
        }
        let flip = self.disk().replace(file, page as u64, older);
        let what = format!("replay of {kind} page {page}");
        let mut outcome = "";
        let mut got = 0u64;
        let detected = |r: &mut Self, e: &EngineError, outcome: &mut &str| -> bool {
            let code = engine_code(e);
            if code != "XX001" {
                r.fail(i, format!("{what}: {code}, not XX001: {e}"));
                return false;
            }
            *outcome = "XX001";
            true
        };
        match self.open_proc(0) {
            Err(e) => {
                if !detected(self, &e, &mut outcome) {
                    return false;
                }
            }
            Ok(()) => {
                got = self.db().version();
                let d = self.committed_digest("main");
                self.drop_proc(0);
                match d {
                    None => {
                        let e = self
                            .digest_err
                            .take()
                            .expect("a failed digest records its error");
                        if !detected(self, &e, &mut outcome) {
                            return false;
                        }
                    }
                    Some(dg) if got == version && dg == last_digest && !deps.contains(&page) => {
                        // The rows are right, so the replayed page was not on their path: the
                        // image checker reads every other reachable page and must find it. (A page
                        // the manifest depends on must have failed the manifest's digest instead.)
                        let replayed = self.image("main").unwrap_or_default();
                        match check::integrity_error(&replayed, got, self.credential("main")) {
                            None => {
                                self.fail(i, format!("{what} went undetected"));
                                return false;
                            }
                            Some(Ok(e)) => {
                                if !detected(self, &e, &mut outcome) {
                                    return false;
                                }
                            }
                            Some(Err(msg)) => {
                                self.fail(i, format!("{what}: non-engine error: {msg}"));
                                return false;
                            }
                        }
                    }
                    Some(dg)
                        if got < version
                            && got == other
                            && deps.contains(&page)
                            && self.main_db().in_history(got, &dg) =>
                    {
                        // The manifest's digest of the page fails, so recovery falls back
                        // (validated-cow.md §1) to an intact older generation.
                        let replayed = self.image("main").unwrap_or_default();
                        if let Err(e) = check::integrity(&replayed, got, self.credential("main")) {
                            self.fail(
                                i,
                                format!(
                                    "{what}: the fallback generation {got} fails the image checker: {e}"
                                ),
                            );
                            return false;
                        }
                        outcome = "fallback";
                    }
                    Some(dg) => {
                        self.fail(
                            i,
                            format!(
                                "{what}: version {got} read back with contents (digest {dg}) the replay must not produce (manifest dependency: {}, other slot {other})",
                                deps.contains(&page)
                            ),
                        );
                        return false;
                    }
                }
            }
        }
        self.disk().process_death();
        self.disk().repair(file, &[flip]);
        if !self.reopen_as_was(i, "replay") {
            return false;
        }
        if outcome == "fallback" {
            self.emit(format!(
                "{{\"i\":{i},\"op\":\"replay\",\"kind\":{},\"page\":{page},\"outcome\":\"fallback\",\"version\":{got}}}",
                go_quote(kind)
            ));
        } else {
            self.emit(format!(
                "{{\"i\":{i},\"op\":\"replay\",\"kind\":{},\"page\":{page},\"outcome\":\"XX001\"}}",
                go_quote(kind)
            ));
        }
        true
    }

    /// `restore <j>` (§8.3 *Restores*, S13): main's j-th newest successful backup (the oldest if
    /// there are fewer) is copied over it as a host would, with every process ended cleanly. Main is
    /// then that backup's generation, under the key it had then; the history above it is forgotten,
    /// so every later commit diverges from the one the backup was taken in.
    fn step_restore(&mut self, i: usize, j: i64) -> bool {
        for pid in self.live_pids() {
            if let Err(e) = self.close_proc(pid) {
                self.fail(i, format!("close: {e}"));
                return false;
            }
        }
        self.close_flushed();
        self.disk().process_death();
        let k = (self.backups_ok.len() as i64 - j).max(0) as usize;
        let usable = self
            .backups_ok
            .get(k)
            .is_some_and(|b| self.disk().file(&b.file).is_some());
        if !usable {
            // Nothing to restore: the processes still end, as the generator's model expects.
            if let Err(e) = self.open() {
                self.fail(i, format!("restore: reopen failed: {e}"));
                return false;
            }
            for name in self.order() {
                self.observe_growth(&name);
            }
            self.emit(format!("{{\"i\":{i},\"op\":\"restore\",\"skip\":true}}"));
            return true;
        }
        let (n, bfile, bversion, bdigest, bkey) = {
            let b = &self.backups_ok[k];
            (b.n, b.file.clone(), b.version, b.digest.clone(), b.key)
        };
        let mfile = self.main_db().file.clone();
        self.disk().restore(&bfile, &mfile);
        {
            let m = self.main_db_mut();
            m.history.retain(|v, _| *v < bversion);
            m.add_history(bversion, bdigest.clone());
            m.version = bversion;
            m.last_digest = bdigest.clone();
            m.floor = bversion;
            m.max_attempted = bversion;
            m.key = bkey;
            m.key_change = None;
            m.owner_lost = false;
            m.shrink_due = false;
        }
        if let Err(e) = self.open() {
            self.fail(i, format!("restore: open failed: {e}"));
            return false;
        }
        let v = self.db().version();
        let d = self.committed_digest("main");
        if v != bversion || d.as_deref() != Some(bdigest.as_str()) {
            self.fail(
                i,
                format!(
                    "restore: main opened at version {v} (digest {}), want the backup's {bversion} (digest {bdigest})",
                    d.unwrap_or_default()
                ),
            );
            return false;
        }
        for name in self.order() {
            self.observe_growth(&name);
        }
        self.emit(format!(
            "{{\"i\":{i},\"op\":\"restore\",\"backup\":{n},\"version\":{v},\"digest\":{}}}",
            go_quote(&bdigest)
        ));
        true
    }

    /// The outcome of opening or reading a corrupted database: without reseal it must be XX001;
    /// with it, any engine error.
    fn corrupt_outcome(&mut self, i: usize, reseal: bool, e: &EngineError) -> Option<String> {
        let code = engine_code(e);
        if code != "XX001" && !reseal {
            self.fail(
                i,
                format!("corrupt: a flipped checksum surfaced as {code}, not XX001: {e}"),
            );
            return None;
        }
        Some(code)
    }
}
